/* DAWAH X — ahmad, অধ্যায় 33 · খণ্ড 33 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][33]=[[6401,6401,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏سَمِعَهُ مِنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَبَّرَ فِي عِيدٍ ثِنْتَيْ عَشْرَةَ تَكْبِيرَةً سَبْعًا فِي الْأُولَى وَخَمْسًا فِي الْآخِرَةِ وَلَمْ يُصَلِّ قَبْلَهَا وَلَا بَعْدَهَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَأَنَا أَذْهَبُ إِلَى هَذَا ‏","","",""],[6402,6402,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَوَّارُ بْنُ دَاوُدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرُوا صِبْيَانَكُمْ بِالصَّلَاةِ إِذَا بَلَغُوا سَبْعًا وَاضْرِبُوهُمْ عَلَيْهَا إِذَا بَلَغُوا عَشْرًا وَفَرِّقُوا بَيْنَهُمْ فِي الْمَضَاجِعِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏الطُّفَاوِيُّ مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏سَوَّارٌ أَبُو حَمْزَةَ ‏ ‏وَأَخْطَأَ فِيهِ ‏","","",""],[6403,6403,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي خُطْبَتِهِ وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏لَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ وَلَا ذُو عَهْدٍ فِي عَهْدِهِ ‏","","",""],[6404,6404,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ تَمْرَةً فِي بَيْتِهِ تَحْتَ جَنْبِهِ فَأَكَلَهَا ‏","","",""],[6405,6405,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏لَمَّا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏عَامَ الْفَتْحِ قَامَ فِي النَّاسِ خَطِيبًا فَقَالَ يَا أَيُّهَا النَّاسُ إِنَّهُ ‏ ‏مَا كَانَ مِنْ حِلْفٍ فِي الْجَاهِلِيَّةِ فَإِنَّ الْإِسْلَامَ لَمْ يَزِدْهُ إِلَّا شِدَّةً وَلَا حِلْفَ فِي الْإِسْلَامِ وَالْمُسْلِمُونَ يَدٌ عَلَى مَنْ سِوَاهُمْ ‏ ‏تَكَافَأُ ‏ ‏دِمَاؤُهُمْ ‏ ‏يُجِيرُ ‏ ‏عَلَيْهِمْ ‏ ‏أَدْنَاهُمْ ‏ ‏وَيَرُدُّ عَلَيْهِمْ أَقْصَاهُمْ تُرَدُّ سَرَايَاهُمْ عَلَى قَعَدِهِمْ لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ دِيَةُ الْكَافِرِ نِصْفُ دِيَةِ الْمُسْلِمِ لَا ‏ ‏جَلَبَ ‏ ‏وَلَا ‏ ‏جَنَبَ ‏ ‏وَلَا تُؤْخَذُ صَدَقَاتُهُمْ إِلَّا فِي دِيَارِهِمْ ‏","","",""],[6406,6406,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ زَادَكُمْ صَلَاةً وَهِيَ الْوَتْرُ ‏","","",""],[6407,6407,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الصَّلَاتَيْنِ فِي السَّفَرِ ‏","","",""],[6408,6408,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُوا وَاشْرَبُوا وَتَصَدَّقُوا وَالْبَسُوا غَيْرَ ‏ ‏مَخِيلَةٍ ‏ ‏وَلَا سَرَفٍ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً فِي غَيْرِ إِسْرَافٍ وَلَا ‏ ‏مَخِيلَةٍ ‏","","",""],[6409,6409,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا كَلِمَاتٍ نَقُولُهُنَّ عِنْدَ النَّوْمِ مِنْ الْفَزَعِ ‏ ‏بِسْمِ اللَّهِ أَعُوذُ بِكَلِمَاتِ اللَّهِ ‏ ‏التَّامَّاتِ ‏ ‏مِنْ غَضَبِهِ وَعِقَابِهِ وَشَرِّ عِبَادِهِ وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏يُعَلِّمُهَا مَنْ بَلَغَ مِنْ وَلَدِهِ أَنْ يَقُولَهَا عِنْدَ نَوْمِهِ وَمَنْ كَانَ مِنْهُمْ صَغِيرًا لَا يَعْقِلُ أَنْ يَحْفَظَهَا كَتَبَهَا لَهُ فَعَلَّقَهَا فِي عُنُقِهِ ‏","","",""],[6410,6410,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَعَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَعَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏وَقَّتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏وَأَهْلِ ‏ ‏تِهَامَةَ ‏ ‏يَلَمْلَمَ ‏ ‏وَلِأَهْلِ ‏ ‏الطَّائِفِ ‏ ‏وَهِيَ ‏ ‏نَجْدٌ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏ذَاتَ عِرْقٍ ‏","","",""],[6411,6411,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَجُوزُ شَهَادَةُ خَائِنٍ وَلَا خَائِنَةٍ وَرَدَّ شَهَادَةَ الْقَانِعِ الْخَادِمِ وَالتَّابِعِ لِأَهْلِ الْبَيْتِ وَأَجَازَهَا لِغَيْرِهِمْ ‏","","",""],[6412,6412,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏أَيُّمَا ‏ ‏مُسْتَلْحَقٍ ‏ ‏اسْتُلْحِقَ ‏ ‏بَعْدَ أَبِيهِ الَّذِي يُدْعَى لَهُ ادَّعَاهُ وَرَثَتُهُ قَضَى إِنْ كَانَ مِنْ حُرَّةٍ تَزَوَّجَهَا أَوْ مِنْ أَمَةٍ يَمْلِكُهَا فَقَدْ لَحِقَ بِمَا ‏ ‏اسْتَلْحَقَهُ ‏ ‏وَإِنْ كَانَ مِنْ حُرَّةٍ أَوْ أَمَةٍ ‏ ‏عَاهَرَ ‏ ‏بِهَا لَمْ يَلْحَقْ بِمَا ‏ ‏اسْتَلْحَقَهُ ‏ ‏وَإِنْ كَانَ أَبُوهُ الَّذِي يُدْعَى لَهُ هُوَ ادَّعَاهُ وَهُوَ ابْنُ زِنْيَةٍ لِأَهْلِ أُمِّهِ مَنْ كَانُوا حُرَّةً أَوْ أَمَةً ‏","","",""],[6413,6413,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَأَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي ذَوِي أَرْحَامٍ أَصِلُ وَيَقْطَعُونِي ‏ ‏وَأَعْفُو وَيَظْلِمُونَ وَأُحْسِنُ وَيُسِيئُونَ أَفَأُكَافِئُهُمْ قَالَ لَا إِذًا تُتْرَكُونَ جَمِيعًا وَلَكِنْ ‏ ‏خُذْ بِالْفَضْلِ وَصِلْهُمْ فَإِنَّهُ لَنْ يَزَالَ مَعَكَ ظَهِيرٌ مِنْ اللَّهِ عَزَّ وَجَلَّ مَا كُنْتَ عَلَى ذَلِكَ ‏","","",""],[6414,6414,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏يُوسُفَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَحْضُرُ الْجُمُعَةَ ثَلَاثَةٌ رَجُلٌ حَضَرَهَا بِدُعَاءٍ وَصَلَاةٍ فَذَلِكَ رَجُلٌ دَعَا رَبَّهُ إِنْ شَاءَ أَعْطَاهُ وَإِنْ شَاءَ مَنَعَهُ وَرَجُلٌ حَضَرَهَا بِسُكُوتٍ وَإِنْصَاتٍ فَذَلِكَ هُوَ حَقُّهَا وَرَجُلٌ يَحْضُرُهَا ‏ ‏يَلْغُو فَذَلِكَ حَظُّهُ مِنْهَا ‏","","",""],[6415,6415,"","","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏لَقَدْ جَلَسْتُ أَنَا وَأَخِي مَجْلِسًا مَا أُحِبُّ أَنَّ لِي بِهِ ‏ ‏حُمْرَ النَّعَمِ ‏ ‏أَقْبَلْتُ أَنَا وَأَخِي وَإِذَا مَشْيَخَةٌ مِنْ صَحَابَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُلُوسٌ عِنْدَ بَابٍ مِنْ أَبْوَابِهِ فَكَرِهْنَا أَنْ نُفَرِّقَ بَيْنَهُمْ فَجَلَسْنَا حَجْرَةً إِذْ ذَكَرُوا آيَةً مِنْ الْقُرْآنِ فَتَمَارَوْا فِيهَا حَتَّى ارْتَفَعَتْ أَصْوَاتُهُمْ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُغْضَبًا قَدْ احْمَرَّ وَجْهُهُ ‏ ‏يَرْمِيهِمْ بِالتُّرَابِ وَيَقُولُ ‏ ‏مَهْلًا يَا قَوْمِ بِهَذَا أُهْلِكَتْ الْأُمَمُ مِنْ قَبْلِكُمْ بِاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ وَضَرْبِهِمْ الْكُتُبَ بَعْضَهَا بِبَعْضٍ إِنَّ الْقُرْآنَ لَمْ يَنْزِلْ يُكَذِّبُ بَعْضُهُ بَعْضًا بَلْ يُصَدِّقُ بَعْضُهُ بَعْضًا فَمَا عَرَفْتُمْ مِنْهُ فَاعْمَلُوا بِهِ وَمَا جَهِلْتُمْ مِنْهُ فَرُدُّوهُ إِلَى عَالِمِهِ ‏","","",""],[6416,6416,"","","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ الْمَرْءُ حَتَّى يُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ ‏ ‏قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏لَعَنَ اللَّهُ دِينًا أَنَا أَكْبَرُ مِنْهُ ‏ ‏يَعْنِي التَّكْذِيبَ بِالْقَدَرِ ‏","","",""],[6417,6417,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ ‏ ‏الْعَاصَ بْنَ وَائِلٍ ‏ ‏نَذَرَ فِي الْجَاهِلِيَّةِ أَنْ يَنْحَرَ مِائَةَ بَدَنَةٍ وَأَنَّ ‏ ‏هِشَامَ بْنَ الْعَاصِي ‏ ‏نَحَرَ حِصَّتَهُ خَمْسِينَ بَدَنَةً وَأَنَّ ‏ ‏عَمْرًا ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ ‏ ‏أَمَّا أَبُوكَ فَلَوْ كَانَ أَقَرَّ بِالتَّوْحِيدِ فَصُمْتَ وَتَصَدَّقْتَ عَنْهُ نَفَعَهُ ذَلِكَ ‏","","",""],[6418,6418,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَرْجِعُ فِي هِبَتِهِ إِلَّا الْوَالِدُ مِنْ وَلَدِهِ وَالْعَائِدُ فِي هِبَتِهِ كَالْعَائِدِ فِي قَيْئِهِ ‏","","",""],[6419,6419,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هِيَ ‏ ‏اللُّوطِيَّةُ ‏ ‏الصُّغْرَى ‏ ‏يَعْنِي الرَّجُلَ يَأْتِي امْرَأَتَهُ فِي ‏ ‏دُبُرِهَا ‏","","",""],[6420,6420,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ابْنِي هَذَا كَانَ بَطْنِي لَهُ وِعَاءً وَحِجْرِي لَهُ حِوَاءً وَثَدْيِي لَهُ ‏ ‏سِقَاءً ‏ ‏وَزَعَمَ أَبُوهُ أَنَّهُ يَنْزِعُهُ مِنِّي قَالَ ‏ ‏أَنْتِ أَحَقُّ بِهِ مَا لَمْ تَنْكِحِي ‏","","",""],[6421,6421,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُوا وَاشْرَبُوا وَتَصَدَّقُوا وَالْبَسُوا فِي غَيْرِ ‏ ‏مَخِيلَةٍ ‏ ‏وَلَا سَرَفٍ إِنَّ اللَّهَ يُحِبُّ أَنْ تُرَى نِعْمَتُهُ عَلَى عَبْدِهِ ‏","","",""],[6422,6422,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا امْرَأَةٍ نَكَحَتْ عَلَى ‏ ‏صَدَاقٍ ‏ ‏أَوْ ‏ ‏حِبَاءٍ ‏ ‏أَوْ ‏ ‏عِدَةٍ ‏ ‏قَبْلَ عِصْمَةِ النِّكَاحِ فَهُوَ لَهَا وَمَا كَانَ بَعْدَ عِصْمَةِ النِّكَاحِ فَهُوَ لِمَنْ أُعْطِيَهُ وَأَحَقُّ مَا يُكْرَمُ عَلَيْهِ الرَّجُلُ ابْنَتُهُ أَوْ أُخْتُهُ ‏","","",""],[6423,6423,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنِي ‏ ‏مَعْمَرٌ ‏ ‏أَنَّ ‏ ‏ابْنَ جُرَيْجٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي ‏ ‏أَنَّ ‏ ‏زِنْبَاعًا أَبَا رَوْحٍ ‏ ‏وَجَدَ ‏ ‏غُلَامًا ‏ ‏لَهُ مَعَ جَارِيَةٍ لَهُ ‏ ‏فَجَدَعَ ‏ ‏أَنْفَهُ ‏ ‏وَجَبَّهُ ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ فَعَلَ هَذَا بِكَ قَالَ ‏ ‏زِنْبَاعٌ ‏ ‏فَدَعَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا حَمَلَكَ عَلَى هَذَا فَقَالَ كَانَ مِنْ أَمْرِهِ كَذَا وَكَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْعَبْدِ ‏ ‏اذْهَبْ فَأَنْتَ حُرٌّ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏فَمَوْلَى ‏ ‏مَنْ أَنَا قَالَ ‏ ‏مَوْلَى ‏ ‏اللَّهِ وَرَسُولِهِ فَأَوْصَى بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُسْلِمِينَ قَالَ فَلَمَّا قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالَ وَصِيَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏نُجْرِي عَلَيْكَ النَّفَقَةَ وَعَلَى عِيَالِكَ فَأَجْرَاهَا عَلَيْهِ حَتَّى قُبِضَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَلَمَّا اسْتُخْلِفَ ‏ ‏عُمَرُ ‏ ‏جَاءَهُ فَقَالَ وَصِيَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ أَيْنَ تُرِيدُ قَالَ ‏ ‏مِصْرَ ‏ ‏فَكَتَبَ ‏ ‏عُمَرُ ‏ ‏إِلَى صَاحِبِ ‏ ‏مِصْرَ ‏ ‏أَنْ يُعْطِيَهُ أَرْضًا يَأْكُلُهَا ‏","","",""],[6424,6424,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كُلِّ إِصْبَعٍ عَشْرٌ مِنْ الْإِبِلِ وَفِي كُلِّ سِنٍّ خَمْسٌ مِنْ الْإِبِلِ وَالْأَصَابِعُ سَوَاءٌ وَالْأَسْنَانُ سَوَاءٌ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَسَمِعْتُ ‏ ‏مَكْحُولًا ‏ ‏يَقُولُ وَلَا يَذْكُرُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏مَا رَأَيْتُ أَحَدًا أَوْرَعَ فِي الْحَدِيثِ مِنْ ‏ ‏مُحَمَّدِ بْنِ رَاشِدٍ ‏","","",""],[6425,6425,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ شُعَيْبٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَنَدَ إِلَى بَيْتٍ فَوَعَظَ النَّاسَ وَذَكَّرَهُمْ قَالَ ‏ ‏لَا ‏ ‏يُصَلِّي أَحَدٌ بَعْدَ الْعَصْرِ حَتَّى اللَّيْلِ وَلَا بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَلَا تُسَافِرُ الْمَرْأَةُ إِلَّا مَعَ ذِي مَحْرَمٍ مَسِيرَةَ ثَلَاثٍ وَلَا تَتَقَدَّمَنَّ امْرَأَةٌ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا ‏","","",""],[6426,6426,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَقِيقَةِ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ لَا يُحِبُّ ‏ ‏الْعُقُوقَ ‏ ‏وَكَأَنَّهُ كَرِهَ ‏ ‏الِاسْمَ قَالُوا يَا رَسُولَ اللَّهِ إِنَّمَا نَسْأَلُكَ عَنْ أَحَدِنَا يُولَدُ لَهُ قَالَ مَنْ أَحَبَّ مِنْكُمْ ‏ ‏أَنْ ‏ ‏يَنْسُكَ ‏ ‏عَنْ وَلَدِهِ فَلْيَفْعَلْ عَنْ الْغُلَامِ شَاتَانِ مُكَافَأَتَانِ وَعَنْ ‏ ‏الْجَارِيَةِ ‏ ‏شَاةٌ قَالَ وَسُئِلَ عَنْ ‏ ‏الْفَرَعِ ‏ ‏قَالَ ‏ ‏وَالْفَرَعُ ‏ ‏حَقٌّ وَأَنْ تَتْرُكَهُ حَتَّى يَكُونَ ‏ ‏شُغْزُبًّا ‏ ‏أَوْ ‏ ‏شُغْزُوبًّا ‏ ‏ابْنَ مَخَاضٍ ‏ ‏أَوْ ‏ ‏ابْنَ لَبُونٍ ‏ ‏فَتَحْمِلَ عَلَيْهِ فِي سَبِيلِ اللَّهِ أَوْ تُعْطِيَهُ أَرْمَلَةً خَيْرٌ مِنْ أَنْ تَذْبَحَهُ يَلْصَقُ لَحْمُهُ بِوَبَرِهِ وَتُكْفِئُ إِنَاءَكَ وَتُولِهُ نَاقَتَكَ وَقَالَ وَسُئِلَ عَنْ ‏ ‏الْعَتِيرَةِ ‏ ‏فَقَالَ ‏ ‏الْعَتِيرَةُ ‏ ‏حَقٌّ ‏ ‏قَالَ ‏ ‏بَعْضُ الْقَوْمِ ‏ ‏لِعَمْرِو بْنِ شُعَيْبٍ ‏ ‏مَا ‏ ‏الْعَتِيرَةُ ‏ ‏قَالَ ‏ ‏كَانُوا يَذْبَحُونَ فِي رَجَبٍ شَاةً فَيَطْبُخُونَ وَيَأْكُلُونَ وَيُطْعِمُونَ ‏","","",""],[6427,6427,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْرَكَ رَجُلَيْنِ وَهُمَا مُقْتَرِنَانِ يَمْشِيَانِ إِلَى الْبَيْتِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَالُ الْقِرَانِ قَالَا يَا رَسُولَ اللَّهِ نَذَرْنَا أَنْ نَمْشِيَ إِلَى ‏ ‏الْبَيْتِ ‏ ‏مُقْتَرِنَيْنِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ هَذَا نَذْرًا فَقَطَعَ قِرَانَهُمَا ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏فِي حَدِيثِهِ إِنَّمَا ‏ ‏النَّذْرُ ‏ ‏مَا ابْتُغِيَ بِهِ وَجْهُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[6428,6428,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُصُّ إِلَّا أَمِيرٌ أَوْ مَأْمُورٌ أَوْ مُرَاءٍ فَقُلْتُ لَهُ إِنَّمَا كَانَ يَبْلُغُنَا أَوْ مُتَكَلِّفٌ قَالَ هَكَذَا سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏","","",""],[6429,6429,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّ ‏ ‏عَقْلَ أَهْلِ الْكِتَابَيْنِ نِصْفُ عَقْلِ الْمُسْلِمِينَ ‏ ‏وَهُمْ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏","","",""],[6430,6430,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَ مُتَعَمِّدًا دُفِعَ إِلَى ‏ ‏أَوْلِيَاءِ ‏ ‏الْقَتِيلِ فَإِنْ شَاءُوا قَتَلُوهُ وَإِنْ شَاءُوا أَخَذُوا ‏ ‏الدِّيَةَ ‏ ‏وَهِيَ ثَلَاثُونَ ‏ ‏حِقَّةً ‏ ‏وَثَلَاثُونَ ‏ ‏جَذَعَةً ‏ ‏وَأَرْبَعُونَ خَلِفَةً وَذَلِكَ ‏ ‏عَقْلُ ‏ ‏الْعَمْدِ وَمَا صَالَحُوا عَلَيْهِ فَهُوَ لَهُمْ وَذَلِكَ تَشْدِيدُ ‏ ‏الْعَقْلِ ‏","","",""],[6431,6431,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَقْلُ ‏ ‏شِبْهِ الْعَمْدِ مُغَلَّظٌ مِثْلُ ‏ ‏عَقْلِ ‏ ‏الْعَمْدِ وَلَا يُقْتَلُ صَاحِبُهُ وَذَلِكَ أَنْ ‏ ‏يَنْزُوَ ‏ ‏الشَّيْطَانُ بَيْنَ النَّاسِ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏فَيَكُونُ ‏ ‏رِمِّيًّا فِي ‏ ‏عِمِّيًّا ‏ ‏فِي غَيْرِ فِتْنَةٍ وَلَا حَمْلِ سِلَاحٍ ‏","","",""],[6432,6432,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى مَنْ قُتِلَ خَطَأً ‏ ‏فَدِيَتُهُ ‏ ‏مِائَةٌ مِنْ الْإِبِلِ ‏","","",""],[6433,6433,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ نَائِمًا فَوَجَدَ تَمْرَةً تَحْتَ جَنْبِهِ فَأَخَذَهَا فَأَكَلَهَا ثُمَّ جَعَلَ ‏ ‏يَتَضَوَّرُ ‏ ‏مِنْ آخِرِ اللَّيْلِ وَفَزِعَ لِذَلِكَ بَعْضُ أَزْوَاجِهِ فَقَالَ ‏ ‏إِنِّي وَجَدْتُ تَمْرَةً تَحْتَ جَنْبِي فَأَكَلْتُهَا فَخَشِيتُ أَنْ تَكُونَ مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏","","",""],[6434,6434,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَائِعُ وَالْمُبْتَاعُ بِالْخِيَارِ حَتَّى يَتَفَرَّقَا إِلَّا أَنْ يَكُونَ ‏ ‏سَفْقَةَ خِيَارٍ ‏ ‏وَلَا يَحِلُّ لَهُ أَنْ يُفَارِقَهُ خَشْيَةَ أَنْ يَسْتَقِيلَهُ ‏","","",""],[6435,6435,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏كَتَبَ إِلَى عَامِلٍ لَهُ عَلَى أَرْضٍ لَهُ أَنْ لَا تَمْنَعْ فَضْلَ مَائِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَنَعَ فَضْلَ الْمَاءِ لِيَمْنَعَ بِهِ فَضْلَ ‏ ‏الْكَلَإِ ‏ ‏مَنَعَهُ اللَّهُ يَوْمَ الْقِيَامَةِ فَضْلَهُ ‏","","",""],[6436,6436,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏أَخْبَرَنِي ‏ ‏الثِّقَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْعُرْبَانِ ‏","","",""],[6437,6437,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا وَلَا ‏ ‏رَصَدَ ‏ ‏بِطَرِيقٍ ‏","","",""],[6438,6438,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبٌ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ ‏ ‏أَبَا ثَعْلَبَةَ الْخُشَنِيَّ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي كِلَابًا ‏ ‏مُكَلَّبَةً ‏ ‏فَأَفْتِنِي فِي صَيْدِهَا فَقَالَ ‏ ‏إِنْ كَانَتْ لَكَ كِلَابٌ ‏ ‏مُكَلَّبَةٌ ‏ ‏فَكُلْ مِمَّا أَمْسَكَتْ عَلَيْكَ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏ذَكِيٌّ ‏ ‏وَغَيْرُ ‏ ‏ذَكِيٍّ ‏ ‏قَالَ ‏ ‏ذَكِيٌّ ‏ ‏وَغَيْرُ ‏ ‏ذَكِيٍّ ‏ ‏قَالَ وَإِنْ أَكَلَ مِنْهُ قَالَ وَإِنْ أَكَلَ مِنْهُ قَالَ يَا رَسُولَ اللَّهِ أَفْتِنِي فِي قَوْسِي قَالَ كُلْ مَا أَمْسَكَتْ عَلَيْكَ قَوْسُكَ قَالَ ‏ ‏ذَكِيٌّ ‏ ‏وَغَيْرُ ‏ ‏ذَكِيٍّ ‏ ‏قَالَ ‏ ‏ذَكِيٌّ ‏ ‏وَغَيْرُ ‏ ‏ذَكِيٍّ ‏ ‏قَالَ وَإِنْ تَغَيَّبَ عَنِّي قَالَ وَإِنْ تَغَيَّبَ عَنْكَ مَا لَمْ يَصِلَّ ‏ ‏يَعْنِي يَتَغَيَّرْ ‏ ‏أَوْ تَجِدْ فِيهِ أَثَرَ غَيْرِ سَهْمِكَ قَالَ يَا رَسُولَ اللَّهِ أَفْتِنَا فِي آنِيَةِ ‏ ‏الْمَجُوسِ ‏ ‏إِذَا اضْطُرِرْنَا إِلَيْهَا قَالَ إِذَا اضْطُرِرْتُمْ إِلَيْهَا فَاغْسِلُوهَا بِالْمَاءِ وَاطْبُخُوا فِيهَا ‏","","",""],[6439,6439,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّاسٌ الْجَزَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا عَبْدٍ ‏ ‏كَاتَبَ ‏ ‏عَلَى مِائَةِ ‏ ‏أُوقِيَّةٍ ‏ ‏فَأَدَّاهَا إِلَّا عَشْرَةَ ‏ ‏أَوَاقٍ ‏ ‏فَهُوَ عَبْدٌ وَأَيُّمَا عَبْدٍ ‏ ‏كَاتَبَ ‏ ‏عَلَى مِائَةِ دِينَارٍ فَأَدَّاهَا إِلَّا عَشَرَةَ دَنَانِيرَ فَهُوَ عَبْدٌ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏كَذَا قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏عَبَّاسٌ الْجَزَرِيُّ ‏ ‏كَانَ فِي النُّسْخَةِ ‏ ‏عَبَّاسٌ الْجُوَيْرِيُّ ‏ ‏فَأَصْلَحَهُ أَبِي كَمَا قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏الْجَزَرِيُّ ‏","","",""],[6440,6440,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ الْفَتْحِ ‏ ‏لَا يَجُوزُ لِامْرَأَةٍ عَطِيَّةٌ إِلَّا بِإِذْنِ زَوْجِهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِثْلَهُ ‏","","",""],[6441,6441,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏وَجَاءَتْهُ وُفُودُ ‏ ‏هَوَازِنَ ‏ ‏فَقَالُوا يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّا أَصْلٌ وَعَشِيرَةٌ ‏ ‏فَمُنَّ ‏ ‏عَلَيْنَا ‏ ‏مَنَّ ‏ ‏اللَّهُ عَلَيْكَ فَإِنَّهُ قَدْ نَزَلَ بِنَا مِنْ الْبَلَاءِ مَا لَا ‏ ‏يَخْفَى عَلَيْكَ فَقَالَ ‏ ‏اخْتَارُوا بَيْنَ نِسَائِكُمْ وَأَمْوَالِكُمْ وَأَبْنَائِكُمْ قَالُوا خَيَّرْتَنَا بَيْنَ أَحْسَابِنَا وَأَمْوَالِنَا نَخْتَارُ أَبْنَاءَنَا فَقَالَ أَمَّا مَا كَانَ لِي ‏ ‏وَلِبَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَهُوَ لَكُمْ فَإِذَا صَلَّيْتُ الظُّهْرَ فَقُولُوا إِنَّا نَسْتَشْفِعُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمُؤْمِنِينَ وَبِالْمُؤْمِنِينَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نِسَائِنَا وَأَبْنَائِنَا قَالَ فَفَعَلُوا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا مَا كَانَ لِي ‏ ‏وَلِبَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَهُوَ لَكُمْ وَقَالَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَمَا كَانَ لَنَا فَهُوَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏مِثْلَ ذَلِكَ وَقَالَ ‏ ‏عُيَيْنَةُ بْنُ بَدْرٍ ‏ ‏أَمَّا مَا كَانَ لِي ‏ ‏ولِبَنِي فَزَارَةَ ‏ ‏فَلَا وَقَالَ ‏ ‏الْأَقْرَعُ بْنُ حَابِسٍ ‏ ‏أَمَّا أَنَا ‏ ‏وَبَنُو تَمِيمٍ ‏ ‏فَلَا وَقَالَ ‏ ‏عَبَّاسُ بْنُ مِرْدَاسٍ ‏ ‏أَمَّا أَنَا ‏ ‏وَبَنُو سُلَيْمٍ ‏ ‏فَلَا فَقَالَتْ الْحَيَّانِ كَذَبْتَ بَلْ هُوَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا أَيُّهَا النَّاسُ رُدُّوا عَلَيْهِمْ نِسَاءَهُمْ وَأَبْنَاءَهُمْ فَمَنْ تَمَسَّكَ بِشَيْءٍ مِنْ ‏ ‏الْفَيْءِ ‏ ‏فَلَهُ عَلَيْنَا سِتَّةُ فَرَائِضَ مِنْ أَوَّلِ شَيْءٍ ‏ ‏يُفِيئُهُ ‏ ‏اللَّهُ عَلَيْنَا ثُمَّ رَكِبَ ‏ ‏رَاحِلَتَهُ ‏ ‏وَتَعَلَّقَ بِهِ النَّاسُ يَقُولُونَ اقْسِمْ عَلَيْنَا ‏ ‏فَيْئَنَا ‏ ‏بَيْنَنَا حَتَّى أَلْجَئُوهُ إِلَى ‏ ‏سَمُرَةٍ ‏ ‏فَخَطَفَتْ رِدَاءَهُ فَقَالَ يَا أَيُّهَا النَّاسُ رُدُّوا عَلَيَّ رِدَائِي فَوَاللَّهِ لَوْ كَانَ لَكُمْ بِعَدَدِ شَجَرِ ‏ ‏تِهَامَةَ ‏ ‏نَعَمٌ لَقَسَمْتُهُ بَيْنَكُمْ ثُمَّ لَا تُلْفُونِي بَخِيلًا وَلَا جَبَانًا وَلَا كَذُوبًا ثُمَّ ‏ ‏دَنَا ‏ ‏مِنْ بَعِيرِهِ فَأَخَذَ ‏ ‏وَبَرَةً ‏ ‏مِنْ ‏ ‏سَنَامِهِ ‏ ‏فَجَعَلَهَا بَيْنَ أَصَابِعِهِ السَّبَّابَةِ وَالْوُسْطَى ثُمَّ رَفَعَهَا فَقَالَ يَا أَيُّهَا النَّاسُ لَيْسَ لِي مِنْ هَذَا ‏ ‏الْفَيْءِ ‏ ‏وَلَا هَذِهِ إِلَّا ‏ ‏الْخُمُسُ ‏ ‏وَالْخُمُسُ ‏ ‏مَرْدُودٌ عَلَيْكُمْ فَرُدُّوا الْخِيَاطَ وَالْمَخِيطَ فَإِنَّ ‏ ‏الْغُلُولَ ‏ ‏يَكُونُ عَلَى أَهْلِهِ يَوْمَ الْقِيَامَةِ عَارًا وَنَارًا ‏ ‏وَشَنَارًا ‏ ‏فَقَامَ رَجُلٌ مَعَهُ ‏ ‏كُبَّةٌ ‏ ‏مِنْ شَعَرٍ فَقَالَ إِنِّي أَخَذْتُ هَذِهِ أُصْلِحُ بِهَا بَرْدَعَةَ بَعِيرٍ لِي ‏ ‏دَبِرَ ‏ ‏قَالَ أَمَّا مَا كَانَ لِي ‏ ‏وَلِبَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَهُوَ لَكَ فَقَالَ الرَّجُلُ يَا رَسُولَ اللَّهِ أَمَّا إِذْ بَلَغَتْ مَا أَرَى فَلَا ‏ ‏أَرَبَ ‏ ‏لِي بِهَا ‏ ‏وَنَبَذَهَا ‏","","",""],[6442,6442,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُؤْخَذُ ‏ ‏صَدَقَاتُ ‏ ‏الْمُسْلِمِينَ عَلَى ‏ ‏مِيَاهِهِمْ ‏","","",""],[6443,6443,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ إِنِّي أَعْطَيْتُ أُمِّي حَدِيقَةً حَيَاتَهَا وَإِنَّهَا مَاتَتْ فَلَمْ تَتْرُكْ وَارِثًا غَيْرِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ ‏ ‏صَدَقَتُكَ ‏ ‏وَرَجَعَتْ إِلَيْكَ حَدِيقَتُكَ ‏","","",""],[6444,6444,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَذْرَ إِلَّا فِيمَا ابْتُغِيَ بِهِ وَجْهُ اللَّهِ عَزَّ وَجَلَّ وَلَا يَمِينَ فِي قَطِيعَةِ رَحِمٍ ‏","","",""],[6445,6445,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيَعْرِفْ حَقَّ كَبِيرِنَا ‏","","",""],[6446,6446,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكَسَلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْمَغْرَمِ ‏ ‏وَالْمَأْثَمِ ‏ ‏وَأَعُوذُ بِكَ مِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ ‏","","",""],[6447,6447,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَأَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَلَا أُخْبِرُكُمْ بِأَحَبِّكُمْ إِلَيَّ وَأَقْرَبِكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ فَسَكَتَ الْقَوْمُ فَأَعَادَهَا مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏قَالَ الْقَوْمُ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ أَحْسَنُكُمْ خُلُقًا ‏","","",""],[6448,6448,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَتَرْكُهَا كَفَّارَتُهَا ‏","","",""],[6449,6449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ الْمَكِّيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْلَمِيُّ يَعْنِي عَبْدَ اللَّهِ بْنَ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏عَقَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْغُلَامِ شَاتَيْنِ وَعَنْ ‏ ‏الْجَارِيَةِ ‏ ‏شَاةً ‏","","",""],[6450,6450,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[6451,6451,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏قَيْصَرَ التُّجِيبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ شَابٌّ فَقَالَ يَا رَسُولَ اللَّهِ أُقَبِّلُ وَأَنَا صَائِمٌ قَالَ لَا فَجَاءَ شَيْخٌ فَقَالَ أُقَبِّلُ وَأَنَا صَائِمٌ قَالَ نَعَمْ قَالَ فَنَظَرَ بَعْضُنَا إِلَى بَعْضٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ عَلِمْتُ لِمَ نَظَرَ بَعْضُكُمْ إِلَى بَعْضٍ ‏ ‏إِنَّ الشَّيْخَ يَمْلِكُ نَفْسَهُ ‏","","",""],[6452,6452,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏وَدَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ مِائَتَيْ مَرَّةٍ فِي كُلِّ يَوْمٍ لَمْ يَسْبِقْهُ أَحَدٌ كَانَ قَبْلَهُ وَلَا يُدْرِكُهُ أَحَدٌ بَعْدَهُ إِلَّا بِأَفْضَلَ مِنْ عَمَلِهِ ‏","","",""],[6453,6453,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمًا ‏ ‏يَتَدَارَءُونَ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِهَذَا ضَرَبُوا كِتَابَ اللَّهِ بَعْضَهُ بِبَعْضٍ وَإِنَّمَا نَزَلَ كِتَابُ اللَّهِ يُصَدِّقُ بَعْضُهُ بَعْضًا فَلَا تُكَذِّبُوا بَعْضَهُ بِبَعْضٍ فَمَا عَلِمْتُمْ مِنْهُ فَقُولُوا وَمَا جَهِلْتُمْ ‏ ‏فَكِلُوهُ ‏ ‏إِلَى عَالِمِهِ ‏","","",""],[6454,6454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا وَلَا رَصَدَ بِطَرِيقٍ وَمَنْ قُتِلَ عَلَى غَيْرِ ذَلِكَ فَهُوَ شِبْهُ الْعَمْدِ ‏ ‏وَعَقْلُهُ ‏ ‏مُغَلَّظٌ وَلَا يُقْتَلُ صَاحِبُهُ وَهُوَ ‏ ‏كَالشَّهْرِ الْحَرَامِ لِلْحُرْمَةِ وَالْجِوَارِ ‏","","",""],[6455,6455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قُتِلَ خَطَأً ‏ ‏فَدِيَتُهُ ‏ ‏مِائَةٌ مِنْ الْإِبِلِ ثَلَاثُونَ ‏ ‏بَنَاتُ مَخَاضٍ ‏ ‏وَثَلَاثُونَ ‏ ‏بَنَاتُ لَبُونٍ ‏ ‏وَثَلَاثُونَ ‏ ‏حِقَّةٌ ‏ ‏وَعَشْرٌ ‏ ‏بَنُو لَبُونٍ ‏ ‏ذُكُورٌ ‏","","",""],[6456,6456,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَرَّاجٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ نَفَرًا مِنْ ‏ ‏بَنِي هَاشِمٍ ‏ ‏دَخَلُوا عَلَى ‏ ‏أَسْمَاءَ بِنْتِ عُمَيْسٍ ‏ ‏فَدَخَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَهِيَ تَحْتَهُ يَوْمَئِذٍ فَرَآهُمْ فَكَرِهَ ذَلِكَ فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ لَمْ أَرَ إِلَّا خَيْرًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ قَدْ بَرَّأَهَا مِنْ ذَلِكَ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَقَالَ ‏ ‏لَا يَدْخُلْ رَجُلٌ بَعْدَ يَوْمِي هَذَا عَلَى ‏ ‏مُغِيبَةٍ ‏ ‏إِلَّا وَمَعَهُ رَجُلٌ أَوْ اثْنَانِ ‏","","",""],[6457,6457,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدٍ يَعْنِي أَبَا إِبْرَاهِيمَ الْمُعَقِّبَ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَمْرٍو الْفُقَيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُجَاهِدٌ ‏ ‏عَنْ ‏ ‏جُنَادَةَ بْنِ أَبِي أُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ قَتِيلًا مِنْ ‏ ‏أَهْلِ الذِّمَّةِ ‏ ‏لَمْ ‏ ‏يَرَحْ ‏ ‏رَائِحَةَ الْجَنَّةِ وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا ‏","","",""],[6458,6458,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ الْحَارِثِ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ سَمِعَ رَجُلًا مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاذَا تَقُولُ يَا رَسُولَ اللَّهِ فِي ‏ ‏ضَالَّةِ ‏ ‏الْإِبِلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكَ وَلَهَا مَعَهَا حِذَاؤُهَا وَسِقَاؤُهَا قَالَ ‏ ‏فَضَالَّةُ ‏ ‏الْغَنَمِ قَالَ لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ قَالَ فَمَنْ أَخَذَهَا مِنْ ‏ ‏مَرْتَعِهَا ‏ ‏قَالَ عُوقِبَ ‏ ‏وَغُرِّمَ ‏ ‏مِثْلَ ثَمَنِهَا وَمَنْ اسْتَطْلَقَهَا مِنْ ‏ ‏عِقَالٍ ‏ ‏أَوْ اسْتَخْرَجَهَا مِنْ ‏ ‏حِفْشٍ ‏ ‏وَهِيَ ‏ ‏الْمَظَالُّ ‏ ‏فَعَلَيْهِ الْقَطْعُ قَالَ يَا رَسُولَ اللَّهِ فَالثَّمَرُ يُصَابُ فِي ‏ ‏أَكْمَامِهِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ عَلَى آكِلٍ سَبِيلٌ فَمَنْ اتَّخَذَ ‏ ‏خُبْنَةً ‏ ‏غُرِّمَ ‏ ‏مِثْلَ ثَمَنِهَا وَعُوقِبَ وَمَنْ أَخَذَ شَيْئًا مِنْهَا بَعْدَ أَنْ أَوَى إِلَى ‏ ‏مِرْبَدٍ ‏ ‏أَوْ كَسَرَ عَنْهَا بَابًا فَبَلَغَ مَا يَأْخُذُ ثَمَنَ ‏ ‏الْمِجَنِّ ‏ ‏فَعَلَيْهِ الْقَطْعُ قَالَ يَا رَسُولَ اللَّهِ فَالْكَنْزُ نَجِدُهُ فِي الْخَرِبِ وَفِي ‏ ‏الْآرَامِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[6459,6459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَيْسَ لِي مَالٌ وَلِي يَتِيمٌ فَقَالَ ‏ ‏كُلْ مِنْ مَالِ يَتِيمِكَ غَيْرَ مُسْرِفٍ ‏ ‏أَوْ قَالَ وَلَا ‏ ‏تَفْدِي مَالَكَ بِمَالِهِ شَكَّ ‏ ‏حُسَيْنٌ ‏","","",""],[6460,6460,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ يَعْنِي ابْنَ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرَّاكِبُ شَيْطَانٌ وَالرَّاكِبَانِ شَيْطَانَانِ وَالثَّلَاثَةُ رَكْبٌ ‏","","",""],[6461,6461,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ يَعْنِي أَبَا سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكَسَلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْمَأْثَمِ ‏ ‏وَالْمَغْرَمِ ‏ ‏وَأَعُوذُ بِكَ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ ‏","","",""],[6462,6462,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ ‏ ‏نَوْفًا ‏ ‏وَعَبْدَ اللَّهِ بْنَ عَمْرٍو يَعْنِي ابْنَ الْعَاصِي ‏ ‏اجْتَمَعَا فَقَالَ ‏ ‏نَوْفٌ ‏ ‏لَوْ أَنَّ السَّمَوَاتِ وَالْأَرْضَ وَمَا فِيهِمَا وُضِعَ فِي كِفَّةِ الْمِيزَانِ وَوُضِعَتْ لَا إِلَهَ إِلَّا اللَّهُ فِي الْكِفَّةِ الْأُخْرَى لَرَجَحَتْ بِهِنَّ وَلَوْ أَنَّ السَّمَوَاتِ وَالْأَرْضَ وَمَا فِيهِنَّ كُنَّ طَبَقًا مِنْ حَدِيدٍ فَقَالَ رَجُلٌ لَا إِلَهَ إِلَّا اللَّهُ لَخَرَقَتْهُنَّ حَتَّى تَنْتَهِيَ إِلَى اللَّهِ عَزَّ وَجَلَّ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏صَلَّيْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ فَعَقَّبَ مَنْ عَقَّبَ وَرَجَعَ مَنْ رَجَعَ فَجَاءَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ كَادَ يَحْسِرُ ثِيَابَهُ عَنْ رُكْبَتَيْهِ فَقَالَ أَبْشِرُوا مَعْشَرَ الْمُسْلِمِينَ هَذَا رَبُّكُمْ قَدْ فَتَحَ بَابًا مِنْ أَبْوَابِ السَّمَاءِ ‏ ‏يُبَاهِي بِكُمْ الْمَلَائِكَةَ ‏ ‏يَقُولُ ‏ ‏هَؤُلَاءِ عِبَادِي قَضَوْا فَرِيضَةً وَهُمْ يَنْتَظِرُونَ أُخْرَى ‏","","",""],[6463,6463,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏أَنَّ ‏ ‏نَوْفًا ‏ ‏وَعَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏اجْتَمَعَا ‏ ‏فَقَالَ ‏ ‏نَوْفٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِي ‏ ‏وَأَنَا أُحَدِّثُكَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ صَلَّيْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ ‏ ‏فَعَقَّبَ ‏ ‏مَنْ ‏ ‏عَقَّبَ ‏ ‏وَرَجَعَ مَنْ رَجَعَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ ‏ ‏يَثُوبَ ‏ ‏النَّاسُ لِصَلَاةِ الْعِشَاءِ فَجَاءَ وَقَدْ ‏ ‏حَفَزَهُ ‏ ‏النَّفَسُ رَافِعًا إِصْبَعَهُ هَكَذَا وَعَقَدَ تِسْعًا وَعِشْرِينَ وَأَشَارَ بِإِصْبَعِهِ السَّبَّابَةِ إِلَى السَّمَاءِ وَهُوَ يَقُولُ أَبْشِرُوا مَعْشَرَ الْمُسْلِمِينَ هَذَا رَبُّكُمْ عَزَّ وَجَلَّ قَدْ فَتَحَ بَابًا مِنْ أَبْوَابِ السَّمَاءِ ‏ ‏يُبَاهِي بِكُمْ الْمَلَائِكَةَ يَقُولُ ‏ ‏مَلَائِكَتِي انْظُرُوا إِلَى عِبَادِي أَدَّوْا فَرِيضَةً وَهُمْ يَنْتَظِرُونَ أُخْرَى ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَزْدِيِّ ‏ ‏وَعَنْ ‏ ‏نَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ وَزَادَ فِيهِ وَإِنْ كَادَ ‏ ‏يَحْسِرُ ‏ ‏ثَوْبَهُ عَنْ رُكْبَتَيْهِ وَقَدْ ‏ ‏حَفَزَهُ ‏ ‏النَّفَسُ ‏","","",""],[6464,6464,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا الْخَيْرِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِي ‏ ‏يَقُولُ ‏ ‏إِنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ أَيُّ الْإِسْلَامِ أَفْضَلُ قَالَ ‏ ‏مَنْ سَلِمَ النَّاسُ مِنْ لِسَانِهِ وَيَدِهِ ‏","","",""],[6465,6465,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مُرَيْحٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏مَنْ صَلَّى عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ وَمَلَائِكَتُهُ سَبْعِينَ صَلَاةً ‏","","",""],[6466,6466,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ أُكْسُومٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ حُجَيْرَةَ ‏ ‏يَسْأَلُ ‏ ‏الْقَاسِمَ بْنَ الْبَرْحِيِّ ‏ ‏كَيْفَ سَمِعْتَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِي ‏ ‏يُخْبِرُ قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ خَصْمَيْنِ اخْتَصَمَا إِلَى ‏ ‏عَمْرِو بْنِ الْعَاصِي ‏ ‏فَقَضَى بَيْنَهُمَا فَسَخِطَ الْمَقْضِيُّ عَلَيْهِ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَضَى الْقَاضِي فَاجْتَهَدَ فَأَصَابَ فَلَهُ عَشَرَةُ أُجُورٍ وَإِذَا اجْتَهَدَ فَأَخْطَأَ كَانَ لَهُ أَجْرٌ أَوْ أَجْرَانِ ‏","","",""],[6467,6467,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏الْمَعْنَى وَاحِدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَوَّارٌ أَبُو حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرُوا أَبْنَاءَكُمْ بِالصَّلَاةِ لِسَبْعِ سِنِينَ وَاضْرِبُوهُمْ عَلَيْهَا لِعَشْرِ سِنِينَ وَفَرِّقُوا بَيْنَهُمْ فِي الْمَضَاجِعِ وَإِذَا أَنْكَحَ أَحَدُكُمْ عَبْدَهُ أَوْ أَجِيرَهُ فَلَا يَنْظُرَنَّ إِلَى شَيْءٍ مِنْ عَوْرَتِهِ فَإِنَّ مَا أَسْفَلَ مِنْ سُرَّتِهِ إِلَى رُكْبَتَيْهِ مِنْ عَوْرَتِهِ ‏","","",""],[6468,6468,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنِي ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَعْتَى النَّاسِ عَلَى اللَّهِ عَزَّ وَجَلَّ مَنْ قَتَلَ فِي ‏ ‏حَرَمِ اللَّهِ ‏ ‏أَوْ قَتَلَ غَيْرَ قَاتِلِهِ أَوْ قَتَلَ ‏ ‏بِذُحُولِ ‏ ‏الْجَاهِلِيَّةِ ‏","","",""],[6469,6469,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏نَافِعُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ عَاصِمٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَلَمْ يَشُكَّ ‏ ‏يُونُسُ ‏ ‏قَالَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُبْغِضُ ‏ ‏الْبَلِيغَ ‏ ‏مِنْ الرِّجَالِ الَّذِي ‏ ‏يَتَخَلَّلُ ‏ ‏بِلِسَانِهِ كَمَا ‏ ‏تَتَخَلَّلُ ‏ ‏الْبَاقِرَةُ ‏ ‏بِلِسَانِهَا ‏","","",""],[6470,6470,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏سَمِعْتُ ‏ ‏عَمْرَو بْنَ شُعَيْبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْفَرَعِ ‏ ‏فَقَالَ ‏ ‏الْفَرَعُ ‏ ‏حَقٌّ وَإِنْ تَرَكْتَهُ حَتَّى يَكُونَ ‏ ‏شُغْزُبًّا ‏ ‏ابْنَ مَخَاضٍ ‏ ‏أَوْ ‏ ‏ابْنَ لَبُونٍ ‏ ‏فَتَحْمِلَ عَلَيْهِ فِي سَبِيلِ اللَّهِ أَوْ تُعْطِيَهُ أَرْمَلَةً خَيْرٌ مِنْ أَنْ ‏ ‏تَبُكَّهُ ‏ ‏يَلْصَقُ لَحْمُهُ ‏ ‏بِوَبَرِهِ ‏ ‏وَتَكْفَأَ ‏ ‏إِنَاءَكَ وَتُولِيَ نَاقَتَكَ ‏","","",""],[6471,6471,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي ‏ ‏قَالَ ‏ ‏لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَمْ أُحَدَّثْ أَنَّكَ تَقُومُ اللَّيْلَ ‏ ‏أَوْ أَنْتَ الَّذِي تَقُولُ لَأَقُومَنَّ اللَّيْلَ وَلَأَصُومَنَّ النَّهَارَ ‏ ‏قَالَ أَحْسِبُهُ ‏ ‏قَالَ نَعَمْ يَا رَسُولَ اللَّهِ قَدْ قُلْتُ ذَلِكَ قَالَ ‏ ‏فَقُمْ وَنَمْ وَصُمْ وَأَفْطِرْ وَصُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ وَلَكَ مِثْلُ صِيَامِ الدَّهْرِ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ قَالَ فَصُمْ يَوْمًا وَأَفْطِرْ يَوْمَيْنِ قُلْتُ إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ قَالَ فَصُمْ يَوْمًا وَأَفْطِرْ يَوْمًا وَهُوَ أَعْدَلُ الصِّيَامِ وَهُوَ صِيَامُ ‏ ‏دَاوُدَ ‏ ‏قُلْتُ إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَفْضَلَ مِنْ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏بَلَغَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي أَقُولُ لَأَصُومَنَّ الدَّهْرَ وَلَأَقُومَنَّ اللَّيْلَ مَا بَقِيتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ الَّذِي تَقُولُ ‏ ‏أَوْ قُلْتَ ‏ ‏لَأَصُومَنَّ الدَّهْرَ وَلَأَقُومَنَّ اللَّيْلَ مَا بَقِيتُ قَالَ قُلْتُ نَعَمْ قَالَ فَإِنَّكَ لَا تُطِيقُ ذَلِكَ قَالَ فَقُمْ وَنَمْ وَصُمْ وَأَفْطِرْ وَصُمْ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ فَإِنَّ الْحَسَنَةَ عَشْرُ أَمْثَالِهَا فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏الزُّهْرِيِّ ‏","","",""],[6472,6472,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسِبُهُ قَالَ فِي السُّجُودِ نَحْوَ ذَلِكَ ‏ ‏وَجَعَلَ يَبْكِي فِي سُجُودِهِ وَيَنْفُخُ وَيَقُولُ ‏ ‏رَبِّ لَمْ تَعِدْنِي هَذَا وَأَنَا أَسْتَغْفِرُكَ رَبِّ لَمْ تَعِدْنِي هَذَا وَأَنَا فِيهِمْ فَلَمَّا صَلَّى قَالَ عُرِضَتْ عَلَيَّ الْجَنَّةُ حَتَّى لَوْ مَدَدْتُ يَدِي لَتَنَاوَلْتُ مِنْ قُطُوفِهَا وَعُرِضَتْ عَلَيَّ النَّارُ فَجَعَلْتُ أَنْفُخُ خَشْيَةَ أَنْ ‏ ‏يَغْشَاكُمْ حَرُّهَا وَرَأَيْتُ فِيهَا سَارِقَ ‏ ‏بَدَنَتَيْ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأَيْتُ فِيهَا أَخَا ‏ ‏بَنِي دَعْدَعٍ ‏ ‏سَارِقَ الْحَجِيجِ فَإِذَا ‏ ‏فُطِنَ ‏ ‏لَهُ قَالَ هَذَا عَمَلُ ‏ ‏الْمِحْجَنِ ‏ ‏وَرَأَيْتُ فِيهَا امْرَأَةً طَوِيلَةً سَوْدَاءَ حِمْيَرِيَّةً تُعَذَّبُ فِي ‏ ‏هِرَّةٍ ‏ ‏رَبَطَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تَسْقِهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ حَتَّى مَاتَتْ وَإِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ فَإِذَا انْكَسَفَ أَحَدُهُمَا ‏ ‏أَوْ قَالَ فُعِلَ بِأَحَدِهِمَا شَيْءٌ مِنْ ذَلِكَ ‏ ‏فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏لِمَ تُعَذِّبُهُمْ وَأَنَا فِيهِمْ لِمَ تُعَذِّبُنَا وَنَحْنُ نَسْتَغْفِرُكَ ‏ ‏وَوَافَقَ ‏ ‏شُعْبَةُ ‏ ‏زَائِدَةَ ‏ ‏وَقَالَ ‏ ‏مِنْ خَشَاشِ الْأَرْضِ ‏ ‏حَدَّثَنَاه ‏ ‏مُعَاوِيَةُ ‏","","",""],[6473,6473,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّهُ تَزَوَّجَ امْرَأَةً مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَكَانَ لَا يَأْتِيهَا كَانَ يَشْغَلُهُ الصَّوْمُ وَالصَّلَاةُ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ صُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ قَالَ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ فَمَا زَالَ بِهِ حَتَّى قَالَ لَهُ صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا وَقَالَ لَهُ ‏ ‏اقْرَإِ الْقُرْآنَ فِي كُلِّ شَهْرٍ قَالَ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ قَالَ اقْرَأْهُ فِي كُلِّ خَمْسَ عَشْرَةَ قَالَ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ قَالَ اقْرَأْهُ فِي كُلِّ سَبْعٍ حَتَّى قَالَ اقْرَأْ فِي كُلِّ ثَلَاثٍ وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ عَمَلٍ ‏ ‏شِرَّةً ‏ ‏وَلِكُلِّ ‏ ‏شِرَّةٍ ‏ ‏فَتْرَةٌ ‏ ‏فَمَنْ كَانَتْ ‏ ‏شِرَّتُهُ ‏ ‏إِلَى سُنَّتِي فَقَدْ أَفْلَحَ وَمَنْ كَانَتْ ‏ ‏فَتْرَتُهُ ‏ ‏إِلَى غَيْرِ ذَلِكَ فَقَدْ هَلَكَ ‏","","",""],[6474,6474,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْعَبَّاسِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَأْذِنُهُ فِي الْجِهَادِ فَقَالَ أَحَيٌّ وَالِدَاكَ قَالَ نَعَمْ قَالَ فَفِيهِمَا فَجَاهِدْ ‏","","",""],[6475,6475,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏حَبِيبَ بْنَ أَبِي ثَابِتٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْعَبَّاسِ الشَّاعِرَ ‏ ‏وَكَانَ صَدُوقًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏إِنَّكَ تَصُومُ الدَّهْرَ فَإِذَا صُمْتَ الدَّهْرَ وَقُمْتَ اللَّيْلَ هَجَمَتْ لَهُ الْعَيْنُ وَنَفِهَتْ لَهُ النَّفْسُ ‏ ‏لَا صَامَ مَنْ صَامَ الْأَبَدَ صُمْ ثَلَاثَةَ أَيَّامٍ مِنْ الشَّهْرِ صَوْمَ الدَّهْرِ كُلِّهِ قَالَ قُلْتُ إِنِّي أُطِيقُ قَالَ صُمْ صَوْمَ ‏ ‏دَاوُدَ ‏ ‏فَإِنَّهُ كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا وَلَا يَفِرُّ إِذَا لَاقَى ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏نَهِثَتْ لَهُ النَّفْسُ ‏","","",""],[6476,6476,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَقْرِئُوا الْقُرْآنَ مِنْ أَرْبَعَةٍ مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَسَالِمٍ ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏وَمُعَاذِ بْنِ جَبَلٍ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏","","",""],[6477,6477,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَقَالَ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحِشًا وَلَا مُتَفَحِّشًا ‏","","",""],[6478,6478,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ أَحْسَنَكُمْ خُلُقًا ‏","","",""],[6479,6479,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَرْبَعٌ مَنْ كُنَّ فِيهِ كَانَ مُنَافِقًا أَوْ كَانَتْ فِيهِ خَصْلَةٌ مِنْ الْأَرْبَعِ كَانَتْ فِيهِ خَصْلَةٌ مِنْ النِّفَاقِ حَتَّى يَدَعَهَا إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ أَخْلَفَ وَإِذَا عَاهَدَ غَدَرَ وَإِذَا خَاصَمَ فَجَرَ ‏","","",""],[6480,6480,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَى رَجُلٍ طَلَاقٌ فِيمَا لَا يَمْلِكُ وَلَا عَتَاقٌ فِيمَا لَا يَمْلِكُ وَلَا بَيْعٌ فِيمَا لَا يَمْلِكُ ‏","","",""],[6481,6481,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا افْتَتَحَ ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏لَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا ‏","","",""],[6482,6482,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏جُوَيْرِيَةَ بِنْتِ الْحَارِثِ ‏ ‏وَهِيَ صَائِمَةٌ فِي يَوْمِ جُمُعَةٍ فَقَالَ لَهَا أَصُمْتِ أَمْسِ فَقَالَتْ لَا قَالَ أَتُرِيدِينَ أَنْ تَصُومِي غَدًا فَقَالَتْ لَا قَالَ فَأَفْطِرِي إِذًا ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وَوَافَقَنِي عَلَيْهِ ‏ ‏مَطَرٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏","","",""],[6483,6483,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا فَتَحَ ‏ ‏مَكَّةَ ‏ ‏قَالَ فِي خُطْبَتِهِ ‏ ‏فِي الْأَصَابِعِ عَشْرٌ عَشْرٌ وَفِي ‏ ‏الْمَوَاضِحِ ‏ ‏خَمْسٌ خَمْسٌ ‏","","",""],[6484,6484,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فَسَكِرَ لَمْ تُقْبَلْ صَلَاتُهُ أَرْبَعِينَ لَيْلَةً فَإِنْ شَرِبَهَا فَسَكِرَ لَمْ تُقْبَلْ صَلَاتُهُ أَرْبَعِينَ لَيْلَةً فَإِنْ شَرِبَهَا فَسَكِرَ لَمْ تُقْبَلْ صَلَاتُهُ أَرْبَعِينَ لَيْلَةً وَالثَّالِثَةَ وَالرَّابِعَةَ فَإِنْ شَرِبَهَا لَمْ تُقْبَلْ صَلَاتُهُ أَرْبَعِينَ لَيْلَةً فَإِنْ تَابَ لَمْ يَتُبْ اللَّهُ عَلَيْهِ وَكَانَ حَقًّا عَلَى اللَّهِ أَنْ يُسْقِيَهُ مِنْ عَيْنِ خَبَالٍ قِيلَ وَمَا عَيْنُ خَبَالٍ قَالَ صَدِيدُ أَهْلِ النَّارِ ‏","","",""],[6485,6485,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي ثُمَامَةَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُوضَعُ ‏ ‏الرَّحِمُ ‏ ‏يَوْمَ الْقِيَامَةِ لَهَا ‏ ‏حُجْنَةٌ ‏ ‏كَحُجْنَةِ ‏ ‏الْمِغْزَلِ ‏ ‏تَكَلَّمُ بِلِسَانٍ طَلْقٍ ‏ ‏ذَلْقٍ ‏ ‏فَتَصِلُ مَنْ وَصَلَهَا وَتَقْطَعُ مَنْ قَطَعَهَا ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏الْمِغْزَلُ وَقَالَ بِأَلْسِنَةٍ لَهَا ‏","","",""],[6486,6486,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏أَخِي ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّهُ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كَمْ أَقْرَأُ الْقُرْآنَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏فِي سَبْعٍ لَا يَفْقَهُ مَنْ قَرَأَهُ فِي أَقَلَّ مِنْ ثَلَاثٍ وَقَالَ كَيْفَ أَصُومُ قَالَ صُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ عَشَرَةِ أَيَّامٍ يَوْمًا وَيُكْتَبُ لَكَ أَجْرُ تِسْعَةِ أَيَّامٍ قَالَ إِنِّي أَقْوَى مِنْ ذَلِكَ قَالَ صُمْ مِنْ كُلِّ عَشَرَةٍ يَوْمَيْنِ وَيُكْتَبُ لَكَ أَجْرُ ثَمَانِيَةِ أَيَّامٍ حَتَّى بَلَغَ خَمْسَةَ أَيَّامٍ ‏","","",""],[6487,6487,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ مُسْلِمٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَكَانَ فِي كِتَابِ أَبِي عَنْ ‏ ‏الْحَسَنِ بْنِ مُسْلِمٍ ‏ ‏فَضَرَبَ عَلَى ‏ ‏الْحَسَنِ ‏ ‏وَقَالَ عَنْ ‏ ‏ابْنِ مُسْلِمٍ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ أَبُو الزُّبَيْرِ ‏ ‏أَخْطَأَ ‏ ‏الْأَزْرَقُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتَ أُمَّتِي لَا يَقُولُونَ لِلظَّالِمِ مِنْهُمْ أَنْتَ ظَالِمٌ فَقَدْ تُوُدِّعَ مِنْهُمْ ‏","","",""],[6488,6488,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ يَحْيَى ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏حَسَنٌ الْأَشْيَبُ ‏ ‏رَاشِدٌ أَبُو يَحْيَى الْمَعَافِرِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ الْحُبُلِيَّ ‏ ‏عَنِ ‏ ‏ابْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا غَنِيمَةُ مَجَالِسِ الذِّكْرِ قَالَ ‏ ‏غَنِيمَةُ ‏ ‏مَجَالِسِ الذِّكْرِ الْجَنَّةُ ‏","","",""],[6489,6489,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاشِيَ وَالْمُرْتَشِيَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَعْنَةُ اللَّهِ عَلَى الرَّاشِي وَالْمُرْتَشِي ‏","","",""],[6490,6490,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ ‏ ‏لَعَنَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاشِيَ ‏ ‏وَالْمُرْتَشِيَ ‏","","",""],[6491,6491,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَامِرٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَذْرَ لِابْنِ ‏ ‏آدَمَ ‏ ‏فِيمَا لَا يَمْلِكُ وَلَا عِتْقَ لِابْنِ ‏ ‏آدَمَ ‏ ‏فِيمَا لَا يَمْلِكُ وَلَا طَلَاقَ لَهُ فِيمَا لَا يَمْلِكُ وَلَا يَمِينَ فِيمَا لَا يَمْلِكُ ‏","","",""],[6492,6492,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏مَطَرٌ الْوَرَّاقُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجُوزُ طَلَاقٌ وَلَا بَيْعٌ وَلَا عِتْقٌ وَلَا وَفَاءُ نَذْرٍ فِيمَا لَا يَمْلِكُ ‏","","",""],[6493,6493,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ عِنْدَ ‏ ‏الْجَمْرَةِ الثَّانِيَةِ ‏ ‏أَكْثَرَ مِمَّا وَقَفَ عِنْدَ ‏ ‏الْجَمْرَةِ الْأُولَى ‏ ‏ثُمَّ أَتَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏فَرَمَاهَا وَلَمْ يَقِفْ عِنْدَهَا ‏","","",""],[6494,6494,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدِ بْنِ جُحَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏أَنَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْفَتِلُ ‏ ‏عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ فِي الصَّلَاةِ وَيَشْرَبُ قَائِمًا وَقَاعِدًا وَيُصَلِّي حَافِيًا وَنَاعِلًا وَيَصُومُ فِي السَّفَرِ وَيُفْطِرُ ‏","","",""],[6495,6495,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدٍ الْمُحَارِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتَ أُمَّتِي تَهَابُ الظَّالِمَ أَنْ تَقُولَ لَهُ أَنْتَ ظَالِمٌ فَقَدْ تُوُدِّعَ مِنْهُمْ ‏","","",""],[6496,6496,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَمْرٍو الْفُقَيْمِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ ‏ ‏الْوَاصِلُ ‏ ‏بِالْمُكَافِئِ ‏ ‏وَلَكِنَّ ‏ ‏الْوَاصِلَ ‏ ‏مَنْ إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا ‏","","",""],[6497,6497,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا الْقُرْآنَ مِنْ أَرْبَعَةٍ مِنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏وَمُعَاذِ بْنِ جَبَلٍ ‏ ‏وَسَالِمٍ ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَذَاكَ رَجُلٌ لَا أَزَالُ أُحِبُّهُ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَدَأَ بِهِ ‏","","",""],[6498,6498,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْزِعُهُ مِنْ النَّاسِ وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ حَتَّى إِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُؤَسَاءَ جُهَّالًا فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ أَمْلَى عَلَيَّ ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏مِنْ ‏ ‏فِيهِ إِلَى ‏ ‏فِيَّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[6499,6499,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَمِسْعَرٌ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ الصَّوْمِ صَوْمُ أَخِي ‏ ‏دَاوُدَ ‏ ‏كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا وَلَا يَفِرُّ إِذَا لَاقَى قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَامَ مَنْ صَامَ الْأَبَدَ ‏","","",""],[6500,6500,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا الْقُرْآنَ مِنْ أَرْبَعَةٍ مِنْ ‏ ‏ابْنِ أُمِّ عَبْدٍ ‏ ‏فَبَدَأَ بِهِ وَمِنْ ‏ ‏مُعَاذِ بْنِ جَبَلٍ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏وَسَالِمٍ ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏","","",""],[6501,6501,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏قُرَّةُ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏وَقُرَّةُ بْنُ خَالِدٍ ‏ ‏الْمَعْنَى ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاقْتُلُوهُ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏ائْتُونِي بِرَجُلٍ قَدْ شَرِبَ الْخَمْرَ فِي الرَّابِعَةِ فَلَكُمْ عَلَيَّ أَنْ أَقْتُلَهُ ‏","","",""],[6502,6502,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ الْمُكْتِبِ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ ‏ ‏وَالشُّحَّ ‏ ‏فَإِنَّهُ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ أَمَرَهُمْ بِالظُّلْمِ فَظَلَمُوا وَأَمَرَهُمْ بِالْقَطِيعَةِ فَقَطَعُوا وَأَمَرَهُمْ بِالْفُجُورِ فَفَجَرُوا وَإِيَّاكُمْ وَالظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ وَإِيَّاكُمْ وَالْفُحْشَ فَإِنَّ اللَّهَ لَا يُحِبُّ الْفُحْشَ وَلَا التَّفَحُّشَ قَالَ فَقَامَ إِلَيْهِ ‏ ‏رَجُلٌ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ الْمُسْلِمِينَ أَفْضَلُ قَالَ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ قَالَ فَقَامَ هُوَ ‏ ‏أَوْ آخَرُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ الْجِهَادِ أَفْضَلُ قَالَ مَنْ ‏ ‏عَقَرَ ‏ ‏جَوَادَهُ ‏ ‏وَأُهْرِيقَ ‏ ‏دَمُهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏فِي حَدِيثِهِ ‏ ‏ثُمَّ نَادَاهُ هَذَا ‏ ‏أَوْ غَيْرُهُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ الْهِجْرَةِ أَفْضَلُ قَالَ أَنْ تَهْجُرَ مَا كَرِهَ رَبُّكَ وَهُمَا هِجْرَتَانِ هِجْرَةٌ لِلْبَادِي وَهِجْرَةٌ لِلْحَاضِرِ فَأَمَّا هِجْرَةُ الْبَادِي فَيُطِيعُ إِذَا أُمِرَ وَيُجِيبُ إِذَا دُعِيَ وَأَمَّا هِجْرَةُ الْحَاضِرِ فَهِيَ أَشَدُّهُمَا بَلِيَّةً وَأَعْظَمُهُمَا أَجْرًا ‏","","",""],[6503,6503,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَهُ فِي ظِلِّ ‏ ‏الْكَعْبَةِ ‏ ‏وَهُوَ يُحَدِّثُ النَّاسَ قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَنَزَلْنَا مَنْزِلًا فَمِنَّا مَنْ ‏ ‏يَضْرِبُ ‏ ‏خِبَاءَهُ ‏ ‏وَمِنَّا مَنْ هُوَ فِي ‏ ‏جَشْرِهِ ‏ ‏وَمِنَّا مَنْ ‏ ‏يَنْتَضِلُ ‏ ‏إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ جَامِعَةً قَالَ فَانْتَهَيْتُ إِلَيْهِ وَهُوَ يَخْطُبُ النَّاسَ وَيَقُولُ أَيُّهَا النَّاسُ إِنَّهُ ‏ ‏لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلَّا كَانَ حَقًّا عَلَيْهِ أَنْ يَدُلَّ أُمَّتَهُ عَلَى مَا يَعْلَمُهُ خَيْرًا لَهُمْ وَيُنْذِرَهُمْ مَا يَعْلَمُهُ شَرًّا لَهُمْ أَلَا وَإِنَّ ‏ ‏عَافِيَةَ ‏ ‏هَذِهِ الْأُمَّةِ فِي أَوَّلِهَا وَسَيُصِيبُ آخِرَهَا بَلَاءٌ ‏ ‏وَفِتَنٌ ‏ ‏يُرَقِّقُ بَعْضُهَا بَعْضًا تَجِيءُ ‏ ‏الْفِتْنَةُ ‏ ‏فَيَقُولُ الْمُؤْمِنُ هَذِهِ مُهْلِكَتِي ثُمَّ تَنْكَشِفُ ثُمَّ تَجِيءُ فَيَقُولُ هَذِهِ هَذِهِ ثُمَّ تَجِيءُ فَيَقُولُ هَذِهِ هَذِهِ ثُمَّ تَنْكَشِفُ فَمَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنْ النَّارِ وَيَدْخُلَ الْجَنَّةَ فَلْتُدْرِكْهُ ‏ ‏مَنِيَّتُهُ ‏ ‏وَهُوَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏وَيَأْتِي إِلَى النَّاسِ مَا يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ وَمَنْ بَايَعَ إِمَامًا فَأَعْطَاهُ صَفْقَةَ يَدِهِ وَثَمَرَةَ قَلْبِهِ فَلْيُطِعْهُ إِنْ اسْتَطَاعَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً مَا اسْتَطَاعَ ‏ ‏فَلَمَّا سَمِعْتُهَا أَدْخَلْتُ رَأْسِي بَيْنَ رَجُلَيْنِ وَقُلْتُ فَإِنَّ ابْنَ عَمِّكَ ‏ ‏مُعَاوِيَةَ ‏ ‏يَأْمُرُنَا فَوَضَعَ ‏ ‏جُمْعَهُ ‏ ‏عَلَى جَبْهَتِهِ ثُمَّ ‏ ‏نَكَسَ ‏ ‏ثُمَّ رَفَعَ رَأْسَهُ ‏ ‏فَقَالَ ‏ ‏أَطِعْهُ فِي طَاعَةِ اللَّهِ وَاعْصِهِ فِي مَعْصِيَةِ اللَّهِ قُلْتُ لَهُ أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ أَبُو الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي السَّفَرِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ الصَّائِدِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ جَمَاعَةً عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏فَجَلَسْتُ إِلَيْهِمْ فَإِذَا رَجُلٌ يُحَدِّثُهُمْ فَإِذَا هُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَنَزَلْنَا مَنْزِلًا ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[6504,6504,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏كُنَّا نَأْتِي ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏فَنَتَحَدَّثُ عِنْدَهُ فَذَكَرْنَا يَوْمًا ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏فَقَالَ لَقَدْ ذَكَرْتُمْ رَجُلًا لَا أَزَالُ أُحِبُّهُ مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خُذُوا الْقُرْآنَ مِنْ أَرْبَعَةٍ مِنْ ‏ ‏ابْنِ أُمِّ عَبْدٍ ‏ ‏فَبَدَأَ بِهِ ‏ ‏وَمُعَاذِ بْنِ جَبَلٍ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏وَسَالِمٍ ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏","","",""],[6505,6505,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ وَلَا ذُو عَهْدٍ فِي عَهْدِهِ ‏","","",""],[6506,6506,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي خُطْبَتِهِ وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏الْمُسْلِمُونَ ‏ ‏تَكَافَأُ دِمَاؤُهُمْ ‏ ‏وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ ‏","","",""],[6507,6507,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏رَيْحَانَ بْنِ يَزِيدَ الْعَامِرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحِلُّ ‏ ‏الصَّدَقَةُ ‏ ‏لِغَنِيٍّ وَلَا لِذِي ‏ ‏مِرَّةٍ ‏ ‏سَوِيٍّ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَوِيٍّ ‏ ‏و قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏سَعْدٌ ‏ ‏وَلَا ابْنُهُ ‏ ‏يَعْنِي ‏ ‏إِبْرَاهِيمَ بْنَ سَعْدٍ ‏","","",""],[6508,6508,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُقَالُ لِصَاحِبِ الْقُرْآنِ اقْرَأْ ‏ ‏وَارْقَ ‏ ‏وَرَتِّلْ كَمَا كُنْتَ تُرَتِّلُ فِي الدُّنْيَا فَإِنَّ مَنْزِلَتَكَ عِنْدَ آخِرِ آيَةٍ تَقْرَؤُهَا ‏","","",""],[6509,6509,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ لَمْ أَشْعُرْ نَحَرْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ارْمِ وَلَا حَرَجَ قَالَ آخَرُ يَا رَسُولَ اللَّهِ حَلَقْتُ قَبْلَ أَنْ أَنْحَرَ قَالَ انْحَرْ وَلَا حَرَجَ ‏ ‏فَمَا سُئِلَ يَوْمَئِذٍ عَنْ شَيْءٍ قُدِّمَ وَلَا أُخِّرَ إِلَّا قَالَ افْعَلْ وَلَا حَرَجَ ‏","","",""],[6510,6510,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏قَالَ كَتَبَ إِلَيَّ ‏ ‏عَبْدُ اللَّهِ بْنُ رَبَاحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏هَجَّرْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَإِنَّا لَجُلُوسٌ إِذْ اخْتَلَفَ رَجُلَانِ فِي آيَةٍ فَارْتَفَعَتْ أَصْوَاتُهُمَا فَقَالَ ‏ ‏إِنَّمَا هَلَكَتْ الْأُمَمُ قَبْلَكُمْ بِاخْتِلَافِهِمْ فِي الْكِتَابِ ‏","","",""],[6511,6511,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ يَعْنِي عُبَيْدَ بْنَ الْأَخْنَسِ ‏ ‏حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏كُنْتُ أَكْتُبُ كُلَّ شَيْءٍ أَسْمَعُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرِيدُ حِفْظَهُ فَنَهَتْنِي ‏ ‏قُرَيْشٌ ‏ ‏عَنْ ذَلِكَ وَقَالُوا تَكْتُبُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي الْغَضَبِ وَالرِّضَا فَأَمْسَكْتُ حَتَّى ذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اكْتُبْ فَوَالَّذِي نَفْسِي بِيَدِهِ مَا خَرَجَ مِنْهُ إِلَّا حَقٌّ ‏","","",""],[6512,6512,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْجَالِسِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ ‏","","",""],[6513,6513,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي مُرَيَّةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏النَّفَّاخَانِ فِي السَّمَاءِ الثَّانِيَةِ رَأْسُ أَحَدِهِمَا بِالْمَشْرِقِ وَرِجْلَاهُ بِالْمَغْرِبِ ‏ ‏أَوْ قَالَ رَأْسُ أَحَدِهِمَا بِالْمَغْرِبِ وَرِجْلَاهُ بِالْمَشْرِقِ ‏ ‏يَنْتَظِرَانِ مَتَى يُؤْمَرَانِ يَنْفُخَانِ فِي الصُّورِ فَيَنْفُخَانِ ‏","","",""],[6514,6514,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَسْلَمَ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ شَغَافٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ أَعْرَابِيًّا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصُّورِ فَقَالَ قَرْنٌ يُنْفَخُ فِيهِ ‏","","",""],[6515,6515,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَامِرٌ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَعِنْدَهُ الْقَوْمُ فَتَخَطَّى إِلَيْهِ فَمَنَعُوهُ فَقَالَ دَعُوهُ فَأَتَى حَتَّى جَلَسَ عِنْدَهُ فَقَالَ أَخْبِرْنِي بِشَيْءٍ حَفِظْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏","","",""],[6516,6516,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنْ النَّارِ وَيَدْخُلَ الْجَنَّةَ فَلْتُدْرِكْهُ ‏ ‏مَنِيَّتُهُ ‏ ‏وَهُوَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏وَيَأْتِي إِلَى النَّاسِ مَا يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ ‏","","",""],[6517,6517,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ يُكَنَّى ‏ ‏أَبَا مُوسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أُرَاهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ ‏","","",""],[6518,6518,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمًا يَتَوَضَّئُونَ وَأَعْقَابُهُمْ تَلُوحُ فَقَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏","","",""],[6519,6519,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏يَزِيدَ ‏ ‏أَوْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَرَأَ الْقُرْآنَ فِي أَقَلَّ مِنْ ثَلَاثٍ لَمْ ‏ ‏يَفْقَهْهُ ‏","","",""],[6520,6520,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ ‏ ‏يَسْتَأْذِنُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجِهَادِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَيٌّ وَالِدَاكَ قَالَ نَعَمْ قَالَ فَفِيهِمَا فَجَاهِدْ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏عَنْ الْجِهَادِ فَقَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[6521,6521,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏الْمُكْتِبِ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْهِجْرَةِ أَفْضَلُ قَالَ ‏ ‏أَنْ تَهْجُرَ مَا كَرِهَ رَبُّكَ وَهُمَا هِجْرَتَانِ هِجْرَةُ الْحَاضِرِ وَهِجْرَةُ الْبَادِي فَأَمَّا هِجْرَةُ الْبَادِي فَيُطِيعُ إِذَا أُمِرَ وَيُجِيبُ إِذَا دُعِيَ وَأَمَّا هِجْرَةُ الْحَاضِرِ فَهِيَ أَشَدُّهُمَا بَلِيَّةً وَأَعْظَمُهُمَا أَجْرًا ‏","","",""],[6522,6522,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَنْ الْمُهَاجِرُ قَالَ ‏ ‏مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏","","",""],[6523,6523,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَايَعَ إِمَامًا فَأَعْطَاهُ ثَمَرَةَ قَلْبِهِ وَصَفْقَةَ يَدِهِ فَلْيُطِعْهُ مَا اسْتَطَاعَ ‏","","",""],[6524,6524,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أُرِيدَ مَالُهُ بِغَيْرِ حَقٍّ فَقُتِلَ دُونَهُ فَهُوَ شَهِيدٌ ‏","","",""],[6525,6525,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏فِطْرٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّحِمَ مُعَلَّقَةٌ بِالْعَرْشِ وَلَيْسَ ‏ ‏الْوَاصِلُ ‏ ‏بِالْمُكَافِئِ ‏ ‏وَلَكِنَّ ‏ ‏الْوَاصِلَ ‏ ‏مَنْ إِذَا قَطَعَتْهُ رَحِمُهُ وَصَلَهَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏الْمُوَاصِلُ ‏","","",""],[6526,6526,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحِشًا وَلَا مُتَفَحِّشًا وَكَانَ يَقُولُ ‏ ‏مِنْ خِيَارِكُمْ أَحَاسِنُكُمْ أَخْلَاقًا ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏إِنَّ خِيَارَكُمْ أَحَاسِنُكُمْ أَخْلَاقًا ‏","","",""],[6527,6527,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَفَى لِلْمَرْءِ مِنْ الْإِثْمِ أَنْ يُضِيعَ مَنْ يَقُوتُ ‏","","",""],[6528,6528,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ تَحْتَ جَنْبِهِ تَمْرَةً مِنْ اللَّيْلِ فَأَكَلَهَا فَلَمْ يَنَمْ تِلْكَ اللَّيْلَةَ فَقَالَ بَعْضُ نِسَائِهِ يَا رَسُولَ اللَّهِ أَرِقْتَ الْبَارِحَةَ قَالَ ‏ ‏إِنِّي وَجَدْتُ تَحْتَ جَنْبِي تَمْرَةً فَأَكَلْتُهَا وَكَانَ عِنْدَنَا تَمْرٌ مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَخَشِيتُ أَنْ تَكُونَ مِنْهُ ‏","","",""],[6529,6529,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏رَآنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيَّ ثِيَابٌ ‏ ‏مُعَصْفَرَةٌ ‏ ‏فَقَالَ ‏ ‏أَلْقِهَا فَإِنَّهَا ثِيَابُ الْكُفَّارِ ‏","","",""],[6530,6530,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ الْفَرَّاءُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَقِيقَةِ ‏ ‏فَقَالَ ‏ ‏لَا أُحِبُّ ‏ ‏الْعُقُوقَ ‏ ‏وَمَنْ وُلِدَ لَهُ مَوْلُودٌ فَأَحَبَّ أَنْ يَنْسُكَ عَنْهُ فَلْيَفْعَلْ عَنْ الْغُلَامِ شَاتَانِ ‏ ‏مُكَافَأَتَانِ ‏ ‏وَعَنْ ‏ ‏الْجَارِيَةِ ‏ ‏شَاةٌ ‏","","",""],[6531,6531,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَسَنٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أُرِيدَ مَالُهُ بِغَيْرِ حَقٍّ فَقُتِلَ دُونَهُ فَهُوَ شَهِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏خَلِيفَةَ بْنِ خَيَّاطٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ وَأَسْنَدَ ظَهْرَهُ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏فَذَكَرَهُ ‏","","",""],[6532,6532,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَإِسْحَاقُ يَعْنِي الْأَزْرَقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَحَدٌ مِنْ الْمُسْلِمِينَ ‏ ‏يُبْتَلَى بِبَلَاءٍ فِي جَسَدِهِ إِلَّا أَمَرَ اللَّهُ عَزَّ وَجَلَّ الْحَفَظَةَ الَّذِينَ يَحْفَظُونَهُ ‏ ‏اكْتُبُوا لِعَبْدِي مِثْلَ مَا كَانَ يَعْمَلُ وَهُوَ صَحِيحٌ مَا دَامَ مَحْبُوسًا فِي ‏ ‏وَثَاقِي ‏ ‏وَقَالَ ‏ ‏إِسْحَاقُ ‏ ‏اكْتُبُوا لِعَبْدِي فِي كُلِّ يَوْمٍ وَلَيْلَةٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[6533,6533,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ وَلَا ذُو عَهْدٍ فِي عَهْدِهِ ‏","","",""],[6534,6534,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كَفَى بِالْمَرْءِ إِثْمًا أَنْ يُضِيعَ مَنْ يَقُوتُ ‏","","",""],[6535,6535,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أُرِيدَ مَالُهُ بِغَيْرِ حَقٍّ فَقَاتَلَ فَقُتِلَ فَهُوَ شَهِيدٌ ‏ ‏وَأَحْسِبُ ‏ ‏الْأَعْرَجَ ‏ ‏حَدَّثَنِي عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِثْلَهُ ‏","","",""],[6536,6536,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاشِيَ وَالْمُرْتَشِيَ ‏","","",""],[6537,6537,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي كَبْشَةَ السَّلُولِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعُونَ حَسَنَةً أَعْلَاهُنَّ ‏ ‏مَنِيحَةُ ‏ ‏الْعَنْزِ لَا يَعْمَلُ الْعَبْدُ بِحَسَنَةٍ مِنْهَا رَجَاءَ ثَوَابِهَا وَتَصْدِيقَ مَوْعُودِهَا إِلَّا أَدْخَلَهُ اللَّهُ بِهَا الْجَنَّةَ ‏","","",""],[6538,6538,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمٌ يَعْنِي ابْنَ حَيَّانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مِينَاءَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلَغَنِي أَنَّكَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلَغَنِي أَنَّكَ تَصُومُ النَّهَارَ وَتَقُومُ اللَّيْلَ فَلَا تَفْعَلْ فَإِنَّ لِجَسَدِكَ عَلَيْكَ حَظًّا وَلِعَيْنِكَ عَلَيْكَ حَظًّا وَلِزَوْجِكَ عَلَيْكَ حَظًّا صُمْ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ فَذَلِكَ صَوْمُ الدَّهْرِ قَالَ قُلْتُ إِنَّ بِي قُوَّةً قَالَ ‏ ‏صُمْ صَوْمَ ‏ ‏دَاوُدَ ‏ ‏صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏ابْنُ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏يَا لَيْتَنِي كُنْتُ أَخَذْتُ بِالرُّخْصَةِ ‏ ‏و قَالَ ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏إِنِّي أَجِدُ بِي قُوَّةً ‏","","",""],[6539,6539,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ جِئْتُ لِأُبَايِعَكَ وَتَرَكْتُ أَبَوَيَّ يَبْكِيَانِ قَالَ ‏ ‏فَارْجِعْ إِلَيْهِمَا فَأَضْحِكْهُمَا كَمَا أَبْكَيْتَهُمَا وَأَبَى أَنْ يُبَايِعَهُ ‏","","",""],[6540,6540,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ فَلَنْ يَرَحْ رَائِحَةَ الْجَنَّةِ وَرِيحُهَا يُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ عَامًا ‏","","",""],[6541,6541,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏سَمِعْتُ ‏ ‏سَيْفًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رُشَيْدٍ الْهَجَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏حَدِّثْنِي مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدَعْنِي وَمَا وَجَدْتَ فِي وَسْقِكَ يَوْمَ ‏ ‏الْيَرْمُوكِ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏الْحَكَمَ ‏ ‏سَمِعْتُ ‏ ‏سَيْفًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رُشَيْدٍ الْهَجَرِيِّ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ وَدَعْنَا وَمِمَّا وَجَدْتَ فِي وَسْقَيْكَ ‏","","",""],[6542,6542,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ وَإِيَّاكُمْ وَالْفُحْشَ فَإِنَّ اللَّهَ لَا يُحِبُّ الْفُحْشَ وَلَا التَّفَحُّشَ وَإِيَّاكُمْ وَالشُّحَّ فَإِنَّهُ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ أَمَرَهُمْ بِالْقَطِيعَةِ فَقَطَعُوا وَبِالْبُخْلِ فَبَخِلُوا وَبِالْفُجُورِ فَفَجَرُوا قَالَ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ الْإِسْلَامِ أَفْضَلُ أَنْ يَسْلَمَ الْمُسْلِمُونَ مِنْ لِسَانِكَ وَيَدِكَ قَالَ ذَلِكَ الرَّجُلُ ‏ ‏أَوْ رَجُلٌ آخَرُ ‏ ‏يَا رَسُولَ اللَّهِ فَأَيُّ الْهِجْرَةِ أَفْضَلُ قَالَ أَنْ تَهْجُرَ مَا كَرِهَ اللَّهُ وَالْهِجْرَةُ هِجْرَتَانِ هِجْرَةُ الْحَاضِرِ وَالْبَادِي فَأَمَّا الْبَادِي فَيُطِيعُ إِذَا أُمِرَ وَيُجِيبُ إِذَا دُعِيَ وَأَمَّا الْحَاضِرُ فَأَعْظَمُهُمَا بَلِيَّةً وَأَعْظَمُهُمَا أَجْرًا ‏","","",""],[6543,6543,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏ذَكَرُوا ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَقَالَ ذَاكَ رَجُلٌ لَا أَزَالُ أُحِبُّهُ بَعْدَمَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اسْتَقْرِئُوا الْقُرْآنَ مِنْ أَرْبَعَةٍ مِنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏وَسَالِمٍ ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏وَمُعَاذِ بْنِ جَبَلٍ ‏","","",""],[6544,6544,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏فِي بَيْتِ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يُحَدِّثُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَمَّعَ النَّاسَ بِعَمَلِهِ سَمَّعَ اللَّهُ بِهِ سَامِعَ خَلْقِهِ وَصَغَّرَهُ وَحَقَّرَهُ ‏ ‏قَالَ ‏ ‏فَذَرَفَتْ ‏ ‏عَيْنَا ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏","","",""],[6545,6545,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ أَكْبَرِ الذَّنْبِ أَنْ يَسُبَّ الرَّجُلُ وَالِدَيْهِ قَالُوا وَكَيْفَ يَسُبُّ الرَّجُلُ وَالِدَيْهِ قَالَ يَسُبُّ أَبَا الرَّجُلِ فَيَسُبُّ أَبَاهُ وَيَسُبُّ أُمَّهُ فَيَسُبُّ أُمَّهُ ‏","","",""],[6546,6546,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَرَأَ الْقُرْآنَ فِي أَقَلَّ مِنْ ثَلَاثٍ لَمْ ‏ ‏يَفْقَهْهُ ‏","","",""],[6547,6547,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏سَمِعْتُ ‏ ‏وَهْبَ بْنَ جَابِرٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ مَوْلًى ‏ ‏لِعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ لَهُ إِنِّي أُرِيدُ أَنْ أُقِيمَ هَذَا الشَّهْرَ هَاهُنَا ‏ ‏بِبَيْتِ الْمَقْدِسِ ‏ ‏فَقَالَ لَهُ تَرَكْتَ لِأَهْلِكَ مَا يَقُوتُهُمْ هَذَا الشَّهْرَ قَالَ لَا قَالَ فَارْجِعْ إِلَى أَهْلِكَ فَاتْرُكْ لَهُمْ مَا يَقُوتُهُمْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كَفَى بِالْمَرْءِ إِثْمًا أَنْ يُضِيعَ مَنْ يَقُوتُ ‏","","",""],[6548,6548,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَإِ الْقُرْآنَ فِي شَهْرٍ فَقُلْتُ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ فَلَمْ أَزَلْ أَطْلُبُ إِلَيْهِ حَتَّى قَالَ ‏ ‏اقْرَإِ الْقُرْآنَ فِي خَمْسَةِ أَيَّامٍ وَصُمْ ثَلَاثَةَ أَيَّامٍ مِنْ الشَّهْرِ قُلْتُ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ قَالَ ‏ ‏فَصُمْ أَحَبَّ الصَّوْمِ إِلَى اللَّهِ عَزَّ وَجَلَّ صَوْمِ ‏ ‏دَاوُدَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا ‏","","",""],[6549,6549,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ شَتَّى ‏","","",""],[6550,6550,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ نَفَرًا ‏ ‏كَانُوا جُلُوسًا بِبَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بَعْضُهُمْ أَلَمْ يَقُلْ اللَّهُ كَذَا وَكَذَا وَقَالَ بَعْضُهُمْ أَلَمْ يَقُلْ اللَّهُ كَذَا وَكَذَا فَسَمِعَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ كَأَنَّمَا فُقِئَ فِي وَجْهِهِ حَبُّ الرُّمَّانِ فَقَالَ ‏ ‏بِهَذَا أُمِرْتُمْ ‏ ‏أَوْ بِهَذَا بُعِثْتُمْ ‏ ‏أَنْ تَضْرِبُوا كِتَابَ اللَّهِ بَعْضَهُ بِبَعْضٍ إِنَّمَا ضَلَّتْ الْأُمَمُ قَبْلَكُمْ فِي مِثْلِ هَذَا إِنَّكُمْ لَسْتُمْ مِمَّا هَاهُنَا فِي شَيْءٍ انْظُرُوا الَّذِي أُمِرْتُمْ بِهِ فَاعْمَلُوا بِهِ وَالَّذِي نُهِيتُمْ عَنْهُ فَانْتَهُوا ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَمَطَرٍ الْوَرَّاقِ ‏ ‏وَدَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَى أَصْحَابِهِ وَهُمْ يَتَنَازَعُونَ فِي الْقَدَرِ هَذَا يَنْزِعُ آيَةً وَهَذَا يَنْزِعُ آيَةً ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[6551,6551,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَشْهَدُ بِاللَّهِ لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُحِلُّهَا وَيَحُلُّ بِهِ رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏لَوْ وُزِنَتْ ذُنُوبُهُ بِذُنُوبِ ‏ ‏الثَّقَلَيْنِ ‏ ‏لَوَزَنَتْهَا ‏","","",""],[6552,6552,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْبُدُوا الرَّحْمَنَ وَأَفْشُوا السَّلَامَ وَأَطْعِمُوا الطَّعَامَ وَادْخُلُوا ‏ ‏الْجِنَانَ ‏","","",""],[6553,6553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَجُلًا قَالَ اللَّهُمَّ اغْفِرْ لِي ‏ ‏وَلِمُحَمَّدٍ ‏ ‏وَحْدَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ حَجَبْتَهَا عَنْ نَاسٍ كَثِيرٍ ‏","","",""],[6554,6554,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَاءَتْ ‏ ‏أُمَيْمَةُ بِنْتُ رُقَيْقَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُبَايِعُهُ عَلَى الْإِسْلَامِ فَقَالَ ‏ ‏أُبَايِعُكِ عَلَى أَنْ لَا تُشْرِكِي بِاللَّهِ شَيْئًا وَلَا تَسْرِقِي وَلَا تَزْنِي وَلَا تَقْتُلِي وَلَدَكِ وَلَا تَأْتِي ‏ ‏بِبُهْتَانٍ ‏ ‏تَفْتَرِينَهُ بَيْنَ يَدَيْكِ وَرِجْلَيْكِ وَلَا تَنُوحِي وَلَا تَبَرَّجِي تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى ‏","","",""],[6555,6555,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ الْأَلْهَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي رَاشِدٍ الْحُبْرَانِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏فَقُلْتُ لَهُ حَدِّثْنَا مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَلْقَى بَيْنَ يَدَيَّ صَحِيفَةً فَقَالَ هَذَا مَا كَتَبَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرْتُ فِيهَا فَإِذَا فِيهَا أَنَّ ‏ ‏أَبَا بَكْرٍ الصِّدِّيقَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ عَلِّمْنِي مَا أَقُولُ إِذَا أَصْبَحْتُ وَإِذَا أَمْسَيْتُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏قُلْ ‏ ‏اللَّهُمَّ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ لَا إِلَهَ إِلَّا أَنْتَ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ ‏","","",""],[6556,6556,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُغِيرَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ الْغَازِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏هَبَطْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏ثَنِيَّةِ أَذَاخِرَ ‏ ‏قَالَ فَنَظَرَ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا عَلَيَّ ‏ ‏رَيْطَةٌ ‏ ‏مُضَرَّجَةٌ ‏ ‏بِعُصْفُرٍ ‏ ‏فَقَالَ مَا هَذِهِ فَعَرَفْتُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَرِهَهَا فَأَتَيْتُ أَهْلِي وَهُمْ ‏ ‏يَسْجُرُونَ ‏ ‏تَنُّورَهُمْ ‏ ‏فَلَفَفْتُهَا ثُمَّ أَلْقَيْتُهَا فِيهِ ثُمَّ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا فَعَلَتْ ‏ ‏الرَّيْطَةُ ‏ ‏قَالَ قُلْتُ قَدْ عَرَفْتُ مَا كَرِهْتَ مِنْهَا فَأَتَيْتُ أَهْلِي وَهُمْ ‏ ‏يَسْجُرُونَ ‏ ‏تَنُّورَهُمْ ‏ ‏فَأَلْقَيْتُهَا فِيهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَلَّا كَسَوْتَهَا بَعْضَ أَهْلِكَ وَذَكَرَ أَنَّهُ حِينَ هَبَطَ بِهِمْ مِنْ ‏ ‏ثَنِيَّةِ أَذَاخِرَ ‏ ‏صَلَّى بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى جَدْرٍ اتَّخَذَهُ قِبْلَةً فَأَقْبَلَتْ ‏ ‏بَهْمَةٌ ‏ ‏تَمُرُّ بَيْنَ يَدَيْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا زَالَ ‏ ‏يُدَارِئُهَا ‏ ‏وَيَدْنُو ‏ ‏مِنْ الْجَدْرِ حَتَّى نَظَرْتُ إِلَى بَطْنِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ لَصِقَ بِالْجِدَارِ وَمَرَّتْ مِنْ خَلْفِهِ ‏","","",""],[6557,6557,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا كَبْشَةَ السَّلُولِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعُونَ حَسَنَةً أَعْلَاهَا ‏ ‏مِنْحَةُ ‏ ‏الْعَنْزِ مَا مِنْهَا حَسَنَةٌ يَعْمَلُ بِهَا عَبْدٌ رَجَاءَ ‏ ‏ثَوَابِهَا وَتَصْدِيقَ مَوْعُودِهَا إِلَّا أَدْخَلَهُ اللَّهُ بِهَا الْجَنَّةَ ‏","","",""],[6558,6558,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُهَاجِرٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ رُوَيْمٍ ‏ ‏عَنِ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏الَّذِي كَانَ يَسْكُنُ ‏ ‏بَيْتَ الْمَقْدِسِ ‏ ‏قَالَ ‏ ‏ثُمَّ سَأَلْتُهُ هَلْ سَمِعْتَ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ شَارِبَ الْخَمْرِ بِشَيْءٍ قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَشْرَبُ الْخَمْرَ أَحَدٌ مِنْ أُمَّتِي فَيَقْبَلَ اللَّهُ مِنْهُ صَلَاةً أَرْبَعِينَ صَبَاحًا ‏","","",""],[6559,6559,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ خَلَقَ خَلْقَهُ ثُمَّ جَعَلَهُمْ فِي ظُلْمَةٍ ثُمَّ أَخَذَ مِنْ نُورِهِ مَا شَاءَ فَأَلْقَاهُ عَلَيْهِمْ فَأَصَابَ النُّورُ مَنْ شَاءَ أَنْ يُصِيبَهُ وَأَخْطَأَ مَنْ شَاءَ فَمَنْ أَصَابَهُ النُّورُ يَوْمَئِذٍ فَقَدْ اهْتَدَى وَمَنْ أَخْطَأَ يَوْمَئِذٍ ضَلَّ فَلِذَلِكَ قُلْتُ جَفَّ الْقَلَمُ بِمَا هُوَ كَائِنٌ ‏","","",""],[6560,6560,"","","‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ أَبِي إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ جُنَادَةَ الْمَعَافِرِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ الْحُبُلِيَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏حَدَّثَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَسَنَتُهُ فَإِذَا فَارَقَ الدُّنْيَا فَارَقَ السِّجْنَ وَالسَّنَةَ ‏","","",""],[6561,6561,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ هِلَالٍ الصَّدَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّ رَصَاصَةً مِثْلَ هَذِهِ وَأَشَارَ إِلَى مِثْلِ جُمْجُمَةٍ أُرْسِلَتْ مِنْ السَّمَاءِ إِلَى الْأَرْضِ وَهِيَ مَسِيرَةُ خَمْسِ مِائَةِ سَنَةٍ لَبَلَغَتْ الْأَرْضَ قَبْلَ اللَّيْلِ وَلَوْ أَنَّهَا أُرْسِلَتْ مِنْ رَأْسِ السِّلْسِلَةِ لَسَارَتْ أَرْبَعِينَ خَرِيفًا اللَّيْلَ وَالنَّهَارَ قَبْلَ أَنْ تَبْلُغَ أَصْلَهَا أَوْ قَعْرَهَا ‏ ‏حَدَّثَنَاه ‏ ‏الْحَسَنُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ أَبُو شُجَاعٍ ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[6562,6562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْعَبَّاسِ ‏ ‏وَكَانَ رَجُلًا شَاعِرًا ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْذَنَهُ فِي الْجِهَادِ فَقَالَ أَحَيٌّ وَالِدَاكَ قَالَ نَعَمْ قَالَ فَفِيهِمَا فَجَاهِدْ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏","","",""],[6563,6563,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَظُنُّهُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏شَكَّ ‏ ‏قَامَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَأْذِنُهُ فِي الْجِهَادِ فَقَالَ فَهَلْ لَكَ وَالِدَانِ قَالَ نَعَمْ قَالَ أُمِّي قَالَ ‏ ‏انْطَلِقْ فَبِرَّهَا قَالَ فَانْطَلَقَ يَتَخَلَّلُ الرِّكَابَ ‏","","",""],[6564,6564,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏الشَّامِ ‏ ‏وَكَانَ يَتْبَعُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏وَيَسْمَعُ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَهُ فَلَقِيَ ‏ ‏نَوْفًا ‏ ‏فَقَالَ ‏ ‏نَوْفٌ ‏ ‏ذُكِرَ لَنَا أَنَّ اللَّهَ تَعَالَى قَالَ لِمَلَائِكَتِهِ ادْعُوا لِي عِبَادِي قَالُوا يَا رَبِّ كَيْفَ وَالسَّمَوَاتُ السَّبْعُ دُونَهُمْ وَالْعَرْشُ فَوْقَ ذَلِكَ قَالَ إِنَّهُمْ إِذَا قَالُوا لَا إِلَهَ إِلَّا اللَّهُ اسْتَجَابُوا قَالَ يَقُولُ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏صَلَّيْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْمَغْرِبِ ‏ ‏أَوْ غَيْرَهَا ‏ ‏قَالَ فَجَلَسَ قَوْمٌ أَنَا فِيهِمْ يَنْتَظِرُونَ الصَّلَاةَ الْأُخْرَى قَالَ فَأَقْبَلَ إِلَيْنَا يُسْرِعُ الْمَشْيَ كَأَنِّي أَنْظُرُ إِلَى رَفْعِهِ إِزَارَهُ لِيَكُونَ أَحَثَّ لَهُ فِي الْمَشْيِ فَانْتَهَى إِلَيْنَا فَقَالَ أَلَا أَبْشِرُوا هَذَاكَ رَبُّكُمْ أَمَرَ بِبَابِ السَّمَاءِ الْوُسْطَى ‏ ‏أَوْ قَالَ بِبَابِ السَّمَاءِ ‏ ‏فَفُتِحَ فَفَاخَرَ بِكُمْ الْمَلَائِكَةَ قَالَ ‏ ‏انْظُرُوا إِلَى عِبَادِي أَدَّوْا حَقًّا مِنْ حَقِّي ثُمَّ هُمْ يَنْتَظِرُونَ أَدَاءَ حَقٍّ آخَرَ يُؤَدُّونَهُ ‏","","",""],[6565,6565,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏صُهَيْبٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ذَبَحَ عُصْفُورًا بِغَيْرِ حَقِّهِ سَأَلَهُ اللَّهُ عَزَّ وَجَلَّ عَنْهُ يَوْمَ الْقِيَامَةِ قِيلَ وَمَا حَقُّهُ قَالَ يَذْبَحُهُ ذَبْحًا وَلَا يَأْخُذُ بِعُنُقِهِ فَيَقْطَعَهُ ‏","","",""],[6566,6566,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏بَلَغَنِي أَنَّكَ تَصُومُ النَّهَارَ وَتَقُومُ اللَّيْلَ فَلَا وَلَا تَفْعَلَنَّ فَإِنَّ لِجَسَدِكَ عَلَيْكَ حَظًّا وَإِنَّ لِزَوْجِكَ عَلَيْكَ حَظًّا وَإِنَّ لِعَيْنَيْكَ عَلَيْكَ حَظًّا أَفْطِرْ وَصُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ فَذَلِكَ صَوْمُ الدَّهْرِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ قُوَّةً قَالَ ‏ ‏صُمْ صَوْمَ ‏ ‏دَاوُدَ ‏ ‏صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَقُولُ ‏ ‏يَا لَيْتَنِي كُنْتُ أَخَذْتُ بِالرُّخْصَةِ ‏","","",""],[6567,6567,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ صُمْ مِنْ الشَّهْرِ ثَلَاثَةَ أَيَّامٍ قَالَ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ قَالَ فَمَا زَالَ حَتَّى قَالَ ‏ ‏صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا فَقَالَ لَهُ ‏ ‏اقْرَإِ الْقُرْآنَ فِي كُلِّ شَهْرٍ قَالَ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ قَالَ فَمَا زَالَ حَتَّى قَالَ ‏ ‏اقْرَإِ الْقُرْآنَ فِي كُلِّ ثَلَاثٍ ‏","","",""],[6568,6568,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ مَنْ كُنَّ فِيهِ فَهُوَ مُنَافِقٌ أَوْ كَانَتْ فِيهِ خَصْلَةٌ مِنْ الْأَرْبَعِ كَانَتْ فِيهِ خَصْلَةٌ مِنْ النِّفَاقِ حَتَّى يَدَعَهَا إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ أَخْلَفَ وَإِذَا عَاهَدَ غَدَرَ وَإِذَا خَاصَمَ فَجَرَ ‏","","",""],[6569,6569,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي الْوَاسِطِيَّ الطَّحَّانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سِنَانٍ ضِرَارُ بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْهُذَيْلِ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏النَّخَعِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَسْجِدَ ‏ ‏إِيلِيَاءَ ‏ ‏فَصَلَّيْتُ إِلَى ‏ ‏سَارِيَةٍ ‏ ‏رَكْعَتَيْنِ فَجَاءَ رَجُلٌ فَصَلَّى قَرِيبًا مِنِّي فَمَالَ إِلَيْهِ النَّاسُ فَإِذَا هُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏فَجَاءَهُ رَسُولُ ‏ ‏يَزِيدَ بْنِ مُعَاوِيَةَ ‏ ‏أَنْ أَجِبْ قَالَ هَذَا يَنْهَانِي أَنْ أُحَدِّثَكُمْ كَمَا كَانَ أَبُوهُ يَنْهَانِي وَإِنِّي سَمِعْتُ نَبِيَّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَعُوذُ بِكَ مِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ دُعَاءٍ لَا يُسْمَعُ وَمِنْ عِلْمٍ لَا يَنْفَعُ أَعُوذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ ‏","","",""],[6570,6570,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ الْأَبَدَ فَلَا صَامَ ‏","","",""],[6571,6571,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ أُخْبِرْتُ أَنَّكَ تَقُومُ اللَّيْلَ وَتَصُومُ النَّهَارَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ نَعَمْ قَالَ فَصُمْ وَأَفْطِرْ وَصَلِّ وَنَمْ فَإِنَّ لِجَسَدِكَ عَلَيْكَ حَقًّا وَإِنَّ لِزَوْجِكَ عَلَيْكَ حَقًّا وَإِنَّ لِزَوْرِكَ عَلَيْكَ حَقًّا وَإِنَّ بِحَسْبِكَ أَنْ تَصُومَ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ قَالَ فَشَدَّدْتُ فَشُدِّدَ عَلَيَّ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ قُوَّةً قَالَ فَصُمْ مِنْ كُلِّ جُمُعَةٍ ثَلَاثَةَ أَيَّامٍ قَالَ فَشَدَّدْتُ فَشُدِّدَ عَلَيَّ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ قُوَّةً قَالَ ‏ ‏صُمْ صَوْمَ نَبِيِّ اللَّهِ ‏ ‏دَاوُدَ ‏ ‏وَلَا تَزِدْ عَلَيْهِ قُلْتُ يَا رَسُولَ اللَّهِ وَمَا كَانَ صِيَامُ ‏ ‏دَاوُدَ ‏ ‏قَالَ كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا ‏","","",""],[6572,6572,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ يَوْمَ كَسَفَتْ الشَّمْسُ يَوْمَ مَاتَ ‏ ‏إِبْرَاهِيمُ ‏ ‏ابْنُهُ فَقَامَ بِالنَّاسِ فَقِيلَ لَا يَرْكَعُ فَرَكَعَ فَقِيلَ لَا يَرْفَعُ فَرَفَعَ فَقِيلَ لَا يَسْجُدُ وَسَجَدَ فَقِيلَ لَا يَرْفَعُ فَقَامَ فِي الثَّانِيَةِ فَفَعَلَ مِثْلَ ذَلِكَ وَتَجَلَّتْ الشَّمْسُ ‏","","",""],[6573,6573,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي جِئْتُ لِأُبَايِعَكَ وَتَرَكْتُ أَبَوَيَّ يَبْكِيَانِ قَالَ ‏ ‏فَارْجِعْ إِلَيْهِمَا فَأَضْحِكْهُمَا كَمَا أَبْكَيْتَهُمَا ‏","","",""],[6574,6574,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أَحَدٍ مِنْ الْمُسْلِمِينَ يُصَابُ بِبَلَاءٍ فِي جَسَدِهِ إِلَّا أَمَرَ اللَّهُ تَعَالَى الْحَفَظَةَ الَّذِينَ يَحْفَظُونَهُ قَالَ ‏ ‏اكْتُبُوا لِعَبْدِي فِي كُلِّ يَوْمٍ وَلَيْلَةٍ مِثْلَ مَا كَانَ يَعْمَلُ مِنْ الْخَيْرِ مَا دَامَ مَحْبُوسًا فِي وَثَاقِي ‏","","",""],[6575,6575,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏قَالَ ‏ ‏لَمَّا جَاءَتْنَا بَيْعَةُ ‏ ‏يَزِيدَ بْنِ مُعَاوِيَةَ ‏ ‏قَدِمْتُ ‏ ‏الشَّامَ ‏ ‏فَأُخْبِرْتُ بِمَقَامٍ يَقُومُهُ ‏ ‏نَوْفٌ ‏ ‏فَجِئْتُهُ ‏ ‏إِذْ جَاءَ رَجُلٌ فَاشْتَدَّ النَّاسُ عَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏وَإِذَا هُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏فَلَمَّا رَآهُ ‏ ‏نَوْفٌ ‏ ‏أَمْسَكَ عَنْ الْحَدِيثِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهَا سَتَكُونُ هِجْرَةٌ بَعْدَ هِجْرَةٍ يَنْحَازُ النَّاسُ إِلَى مُهَاجَرِ ‏ ‏إِبْرَاهِيمَ ‏ ‏لَا يَبْقَى فِي الْأَرْضِ إِلَّا شِرَارُ أَهْلِهَا تَلْفِظُهُمْ أَرَضُوهُمْ تَقْذَرُهُمْ نَفْسُ اللَّهِ تَحْشُرُهُمْ النَّارُ مَعَ الْقِرَدَةِ وَالْخَنَازِيرِ تَبِيتُ مَعَهُمْ إِذَا بَاتُوا ‏ ‏وَتَقِيلُ ‏ ‏مَعَهُمْ إِذَا ‏ ‏قَالُوا ‏ ‏وَتَأْكُلُ مَنْ تَخَلَّفَ ‏","","",""],[6576,6576,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَخْرُجُ أُنَاسٌ مِنْ أُمَّتِي مِنْ قِبَلِ الْمَشْرِقِ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏كُلَّمَا خَرَجَ مِنْهُمْ قَرْنٌ قُطِعَ كُلَّمَا خَرَجَ مِنْهُمْ قَرْنٌ قُطِعَ ‏ ‏حَتَّى عَدَّهَا زِيَادَةً عَلَى عَشْرَةِ مَرَّاتٍ ‏ ‏كُلَّمَا خَرَجَ مِنْهُمْ قَرْنٌ قُطِعَ حَتَّى يَخْرُجَ ‏ ‏الدَّجَّالُ ‏ ‏فِي بَقِيَّتِهِمْ ‏","","",""],[6577,6577,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏قَالَ ‏ ‏شَكَّ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏فِي الْحَوْضِ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏أَبُو سَبْرَةَ ‏ ‏رَجُلٌ مِنْ صَحَابَةِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زِيَادٍ ‏ ‏فَإِنَّ أَبَاكَ حِينَ انْطَلَقَ وَافِدًا إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏انْطَلَقْتُ مَعَهُ فَلَقِيتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏فَحَدَّثَنِي مِنْ ‏ ‏فِيهِ إِلَى ‏ ‏فِيَّ حَدِيثًا سَمِعَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمْلَاهُ عَلَيَّ وَكَتَبْتُهُ قَالَ فَإِنِّي أَقْسَمْتُ عَلَيْكَ لَمَا أَعْرَقْتَ هَذَا ‏ ‏الْبِرْذَوْنَ ‏ ‏حَتَّى تَأْتِيَنِي بِالْكِتَابِ قَالَ فَرَكِبْتُ ‏ ‏الْبِرْذَوْنَ ‏ ‏فَرَكَضْتُهُ حَتَّى عَرِقَ فَأَتَيْتُهُ بِالْكِتَابِ فَإِذَا فِيهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ يُبْغِضُ ‏ ‏الْفُحْشَ ‏ ‏وَالتَّفَحُّشَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَا تَقُومُ السَّاعَةُ حَتَّى يُخَوَّنَ الْأَمِينُ وَيُؤْتَمَنَ الْخَائِنُ حَتَّى يَظْهَرَ ‏ ‏الْفُحْشُ ‏ ‏وَالتَّفَحُّشُ ‏ ‏وَقَطِيعَةُ الْأَرْحَامِ وَسُوءُ الْجِوَارِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنَّ مَثَلَ الْمُؤْمِنِ ‏ ‏لَكَمَثَلِ الْقِطْعَةِ مِنْ الذَّهَبِ نَفَخَ عَلَيْهَا صَاحِبُهَا فَلَمْ تَغَيَّرْ وَلَمْ تَنْقُصْ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنَّ مَثَلَ الْمُؤْمِنِ ‏ ‏لَكَمَثَلِ النَّحْلَةِ أَكَلَتْ طَيِّبًا وَوَضَعَتْ طَيِّبًا وَوَقَعَتْ فَلَمْ تُكْسَرْ وَلَمْ تَفْسُدْ قَالَ وَقَالَ أَلَا إِنَّ لِي حَوْضًا مَا بَيْنَ نَاحِيَتَيْهِ كَمَا بَيْنَ ‏ ‏أَيْلَةَ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏أَوْ قَالَ ‏ ‏صَنْعَاءَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏وَإِنَّ فِيهِ مِنْ الْأَبَارِيقِ مِثْلَ الْكَوَاكِبِ هُوَ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ بَعْدَهَا أَبَدًا ‏ ‏قَالَ ‏ ‏أَبُو سَبْرَةَ ‏ ‏فَأَخَذَ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏الْكِتَابَ ‏ ‏فَجَزِعْتُ ‏ ‏عَلَيْهِ فَلَقِيَنِي ‏ ‏يَحْيَى بْنُ يَعْمَرَ ‏ ‏فَشَكَوْتُ ذَلِكَ إِلَيْهِ فَقَالَ وَاللَّهِ لَأَنَا أَحْفَظُ لَهُ مِنِّي لِسُورَةٍ مِنْ الْقُرْآنِ فَحَدَّثَنِي بِهِ ‏ ‏كَمَا كَانَ فِي الْكِتَابِ سَوَاءً ‏","","",""],[6578,6578,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ أَبِي مُلَيْكَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَحْيَى بْنِ حَكِيمِ بْنِ صَفْوَانَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏جَمَعْتُ الْقُرْآنَ فَقَرَأْتُهُ فِي لَيْلَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَخْشَى أَنْ يَطُولَ عَلَيْكَ الزَّمَانُ وَأَنْ تَمَلَّ اقْرَأْ بِهِ فِي كُلِّ شَهْرٍ قُلْتُ أَيْ رَسُولَ اللَّهِ دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَمِنْ شَبَابِي قَالَ ‏ ‏اقْرَأْ بِهِ فِي عِشْرِينَ قُلْتُ أَيْ رَسُولَ اللَّهِ دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَمِنْ شَبَابِي قَالَ اقْرَأْ بِهِ فِي عَشْرٍ قُلْتُ يَا رَسُولَ اللَّهِ دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَمِنْ شَبَابِي قَالَ اقْرَأْ بِهِ فِي كُلِّ سَبْعٍ قُلْتُ يَا رَسُولَ اللَّهِ دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَمِنْ شَبَابِي فَأَبَى ‏","","",""],[6579,6579,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏يَزْعُمُ أَنَّ ‏ ‏أَبَا الْعَبَّاسِ الشَّاعِرَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏بَلَغَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي أَصُومُ أَسْرُدُ وَأُصَلِّي اللَّيْلَ قَالَ فَإِمَّا أَرْسَلَ إِلَيَّ وَإِمَّا لَقِيتُهُ فَقَالَ أَلَمْ أُخْبَرْ أَنَّكَ تَصُومُ وَلَا تُفْطِرُ وَتُصَلِّي اللَّيْلَ فَلَا تَفْعَلْ فَإِنَّ لِعَيْنِكَ حَظًّا وَلِنَفْسِكَ حَظًّا وَلِأَهْلِكَ حَظًّا فَصُمْ وَأَفْطِرْ وَصَلِّ وَنَمْ وَصُمْ مِنْ كُلِّ عَشَرَةِ أَيَّامٍ يَوْمًا وَلَكَ أَجْرُ تِسْعَةٍ قَالَ إِنِّي أَجِدُنِي أَقْوَى مِنْ ذَلِكَ يَا نَبِيَّ اللَّهِ قَالَ ‏ ‏فَصُمْ صِيَامَ ‏ ‏دَاوُدَ ‏ ‏قَالَ فَكَيْفَ كَانَ ‏ ‏دَاوُدُ ‏ ‏يَصُومُ يَا نَبِيَّ اللَّهِ قَالَ كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا وَلَا يَفِرُّ إِذَا لَاقَى قَالَ مَنْ لِي بِهَذِهِ يَا نَبِيَّ اللَّهِ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏فَلَا أَدْرِي كَيْفَ ذَكَرَ صِيَامَ الْأَبَدِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَامَ مَنْ صَامَ الْأَبَدَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَرَوْحٌ ‏ ‏لَا صَامَ مَنْ صَامَ الْأَبَدَ مَرَّتَيْنِ ‏","","",""],[6580,6580,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عُمَرُ بْنُ حَوْشَبٍ ‏ ‏رَجُلٌ صَالِحٌ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏هُذَيْلٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏وَمَنْزِلُهُ فِي الْحِلِّ وَمَسْجِدُهُ فِي ‏ ‏الْحَرَمِ ‏ ‏قَالَ فَبَيْنَا أَنَا عِنْدَهُ رَأَى ‏ ‏أُمَّ سَعِيدٍ ابْنَةَ أَبِي جَهْلٍ ‏ ‏مُتَقَلِّدَةً قَوْسًا وَهِيَ تَمْشِي مِشْيَةَ الرَّجُلِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَنْ هَذِهِ قَالَ ‏ ‏الْهُذَلِيُّ ‏ ‏فَقُلْتُ هَذِهِ ‏ ‏أُمُّ سَعِيدٍ بِنْتُ أَبِي جَهْلٍ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ مِنَّا مَنْ تَشَبَّهَ بِالرِّجَالِ مِنْ النِّسَاءِ وَلَا مَنْ تَشَبَّهَ بِالنِّسَاءِ مِنْ الرِّجَالِ ‏","","",""],[6581,6581,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏فَسَأَلَنِي وَهُوَ يَظُنُّ أَنِّي ‏ ‏لِأُمِّ كُلْثُومٍ ابْنَةِ عُقْبَةَ ‏ ‏فَقُلْتُ إِنَّمَا أَنَا ‏ ‏لِلْكَلْبِيَّةِ ‏ ‏قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْتِي فَقَالَ أَلَمْ أُخْبَرْ أَنَّكَ تَقْرَأُ الْقُرْآنَ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ فَاقْرَأْهُ فِي كُلِّ شَهْرٍ قُلْتُ إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ قَالَ فَاقْرَأْهُ فِي نِصْفِ كُلِّ شَهْرٍ قَالَ قُلْتُ إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ قَالَ ‏ ‏فَاقْرَأْهُ فِي كُلِّ سَبْعٍ لَا تَزِيدَنَّ وَبَلَغَنِي أَنَّكَ تَصُومُ الدَّهْرَ قَالَ قُلْتُ إِنِّي لَأَصُومُهُ يَا رَسُولَ اللَّهِ قَالَ فَصُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ قَالَ قُلْتُ إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ قَالَ فَصُمْ مِنْ كُلِّ جُمُعَةٍ يَوْمَيْنِ قَالَ قُلْتُ إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ قَالَ فَصُمْ صِيَامَ ‏ ‏دَاوُدَ ‏ ‏صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا فَإِنَّهُ أَعْدَلُ الصِّيَامِ عِنْدَ اللَّهِ وَكَانَ لَا يُخْلِفُ إِذَا وَعَدَ وَلَا يَفِرُّ إِذَا لَاقَى ‏","","",""],[6582,6582,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ مُرْنِي بِصِيَامٍ قَالَ صُمْ يَوْمًا وَلَكَ أَجْرُ تِسْعَةٍ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ قُوَّةً فَزِدْنِي قَالَ صُمْ يَوْمَيْنِ وَلَكَ أَجْرُ ثَمَانِيَةِ أَيَّامٍ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ قُوَّةً فَزِدْنِي قَالَ فَصُمْ ثَلَاثَةَ أَيَّامٍ وَلَكَ أَجْرُ سَبْعَةِ أَيَّامٍ قَالَ فَمَا زَالَ يَحُطُّ لِي حَتَّى قَالَ ‏ ‏إِنَّ أَفْضَلَ الصَّوْمِ صَوْمُ أَخِي ‏ ‏دَاوُدَ ‏ ‏أَوْ نَبِيِّ اللَّهِ ‏ ‏دَاوُدَ ‏ ‏شَكَّ ‏ ‏الْجُرَيْرِيُّ ‏ ‏صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَمَّا ضَعُفَ لَيْتَنِي كُنْتُ قَنَعْتُ بِمَا أَمَرَنِي بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[6583,6583,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ بَيْتَهُ فَقَالَ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏أَلَمْ أُخْبَرْ أَنَّكَ ‏ ‏تَكَلَّفُ قِيَامَ اللَّيْلِ وَصِيَامَ النَّهَارِ قَالَ إِنِّي لَأَفْعَلُ فَقَالَ إِنَّ حَسْبَكَ وَلَا أَقُولُ افْعَلْ أَنْ تَصُومَ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ الْحَسَنَةُ عَشْرُ أَمْثَالِهَا فَكَأَنَّكَ قَدْ صُمْتَ الدَّهْرَ كُلَّهُ قَالَ فَغَلَّظْتُ فَغُلِّظَ عَلَيَّ قَالَ فَقُلْتُ إِنِّي لَأَجِدُ قُوَّةً مِنْ ذَلِكَ قَالَ إِنَّ مِنْ حَسْبِكَ أَنْ تَصُومَ كُلَّ جُمُعَةٍ ثَلَاثَةَ أَيَّامٍ قَالَ فَغَلَّظْتُ فَغُلِّظَ عَلَيَّ فَقُلْتُ إِنِّي لَأَجِدُ بِي قُوَّةً فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْدَلُ الصِّيَامِ عِنْدَ اللَّهِ صِيَامُ ‏ ‏دَاوُدَ ‏ ‏نِصْفُ الدَّهْرِ ثُمَّ قَالَ لِنَفْسِكَ عَلَيْكَ حَقٌّ وَلِأَهْلِكَ عَلَيْكَ حَقٌّ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَصُومُ ذَلِكَ الصِّيَامَ حَتَّى أَدْرَكَهُ السِّنُّ وَالضَّعْفُ كَانَ يَقُولُ ‏ ‏لَأَنْ أَكُونَ قَبِلْتُ رُخْصَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبُّ إِلَيَّ مِنْ أَهْلِي وَمَالِي ‏","","",""],[6584,6584,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ الْقَاسِمِ بْنِ الْوَلِيدِ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَذْكُرُهُ عَنْ ‏ ‏أَبِي الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ إِذَا كُنَّ فِي الرَّجُلِ فَهُوَ الْمُنَافِقُ الْخَالِصُ إِنْ حَدَّثَ كَذَبَ وَإِنْ وَعَدَ أَخْلَفَ وَإِنْ اؤْتُمِنَ خَانَ وَمَنْ كَانَتْ فِيهِ خَصْلَةٌ مِنْهُنَّ لَمْ يَزَلْ ‏ ‏يَعْنِي فِيهِ خَصْلَةٌ مِنْ النِّفَاقِ حَتَّى يَدَعَهَا ‏","","",""],[6585,6585,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏دَارَهُ فَسَأَلَنِي وَهُوَ يَظُنُّ أَنِّي مِنْ بَنِي ‏ ‏أُمِّ كُلْثُومٍ ابْنَةِ عُقْبَةَ ‏ ‏فَقُلْتُ لَهُ إِنَّمَا أَنَا ‏ ‏لِلْكَلْبِيَّةِ ابْنَةِ الْأَصْبَغِ ‏ ‏وَقَدْ جِئْتُكَ لِأَسْأَلَكَ عَمَّا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهِدَ إِلَيْكَ ‏ ‏أَوْ قَالَ لَكَ ‏ ‏قَالَ كُنْتُ أَقُولُ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَقْرَأَنَّ الْقُرْآنَ فِي كُلِّ يَوْمٍ ‏ ‏وَلَيْلَةٍ وَلَأَصُومَنَّ الدَّهْرَ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنِّي فَجَاءَنِي فَدَخَلَ عَلَيَّ بَيْتِي فَقَالَ أَلَمْ يَبْلُغْنِي يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏أَنَّكَ تَقُولُ لَأَصُومَنَّ الدَّهْرَ وَلَأَقْرَأَنَّ الْقُرْآنَ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ قَالَ قُلْتُ بَلَى قُلْتُ ذَاكَ يَا نَبِيَّ اللَّهِ قَالَ فَلَا تَفْعَلْ صُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ قَالَ فَقُلْتُ إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ قَالَ فَصُمْ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ قَالَ فَقُلْتُ إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ يَا نَبِيَّ اللَّهِ قَالَ ‏ ‏فَصُمْ يَوْمًا وَأَفْطِرْ يَوْمًا فَإِنَّهُ أَعْدَلُ الصِّيَامِ عِنْدَ اللَّهِ وَهُوَ صِيَامُ ‏ ‏دَاوُدَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَكَانَ لَا يُخْلِفُ إِذَا وَعَدَ وَلَا يَفِرُّ إِذَا لَاقَى وَاقْرَأْ الْقُرْآنَ فِي كُلِّ شَهْرٍ مَرَّةً قَالَ فَقُلْتُ إِنِّي لَأَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ يَا نَبِيَّ اللَّهِ قَالَ فَاقْرَأْهُ فِي كُلِّ نِصْفِ شَهْرٍ مَرَّةً قَالَ قُلْتُ إِنِّي أَقْوَى عَلَى أَكْثَرَ مِنْ ذَلِكَ يَا نَبِيَّ اللَّهِ قَالَ فَاقْرَأْهُ فِي كُلِّ سَبْعٍ لَا تَزِيدَنَّ عَلَى ذَلِكَ ثُمَّ انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[6586,6586,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ يَعْنِي ابْنَ عُلَيَّةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏قَالَ ‏ ‏جَلَسَ ثَلَاثَةُ نَفَرٍ مِنْ الْمُسْلِمِينَ إِلَى ‏ ‏مَرْوَانَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَسَمِعُوهُ وَهُوَ يُحَدِّثُ فِي الْآيَاتِ أَنَّ أَوَّلَهَا خُرُوجُ ‏ ‏الدَّجَّالِ ‏ ‏قَالَ فَانْصَرَفَ النَّفَرُ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَحَدَّثُوهُ بِالَّذِي سَمِعُوهُ مِنْ ‏ ‏مَرْوَانَ ‏ ‏فِي الْآيَاتِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَمْ يَقُلْ ‏ ‏مَرْوَانُ ‏ ‏شَيْئًا قَدْ حَفِظْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مِثْلِ ذَلِكَ حَدِيثًا لَمْ أَنْسَهُ بَعْدُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَوَّلَ الْآيَاتِ خُرُوجًا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا وَخُرُوجُ الدَّابَّةِ ضُحًى فَأَيَّتُهُمَا كَانَتْ قَبْلَ صَاحِبَتِهَا فَالْأُخْرَى عَلَى أَثَرِهَا ثُمَّ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَكَانَ يَقْرَأُ الْكُتُبَ وَأَظُنُّ أُولَاهَا خُرُوجًا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا وَذَلِكَ أَنَّهَا كُلَّمَا غَرَبَتْ أَتَتْ تَحْتَ الْعَرْشِ فَسَجَدَتْ وَاسْتَأْذَنَتْ فِي الرُّجُوعِ فَأُذِنَ لَهَا فِي الرُّجُوعِ حَتَّى إِذَا بَدَا لِلَّهِ أَنْ تَطْلُعَ مِنْ مَغْرِبِهَا فَعَلَتْ كَمَا كَانَتْ تَفْعَلُ أَتَتْ تَحْتَ الْعَرْشِ فَسَجَدَتْ فَاسْتَأْذَنَتْ فِي الرُّجُوعِ فَلَمْ يُرَدَّ عَلَيْهَا شَيْءٌ ثُمَّ تَسْتَأْذِنُ فِي الرُّجُوعِ فَلَا يُرَدُّ عَلَيْهَا شَيْءٌ ثُمَّ تَسْتَأْذِنُ فَلَا يُرَدُّ عَلَيْهَا شَيْءٌ حَتَّى إِذَا ذَهَبَ مِنْ اللَّيْلِ مَا شَاءَ اللَّهُ أَنْ يَذْهَبَ وَعَرَفَتْ أَنَّهُ إِنْ أُذِنَ لَهَا فِي الرُّجُوعِ لَمْ تُدْرِكْ الْمَشْرِقَ قَالَتْ رَبِّ مَا أَبْعَدَ الْمَشْرِقَ مَنْ لِي بِالنَّاسِ حَتَّى إِذَا صَارَ الْأُفُقُ كَأَنَّهُ طَوْقٌ اسْتَأْذَنَتْ فِي الرُّجُوعِ فَيُقَالُ لَهَا مِنْ مَكَانِكِ فَاطْلُعِي فَطَلَعَتْ عَلَى النَّاسِ مِنْ مَغْرِبِهَا ثُمَّ تَلَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏هَذِهِ الْآيَةَ ‏ { ‏يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏}","","",""],[6587,6587,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏نُبَيْطِ بْنِ شَرِيطٍ ‏ ‏قَالَ ‏ ‏غُنْدَرٌ ‏ ‏نُبَيْطِ بْنِ سُمَيْطٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏نُبَيْطِ بْنِ شَرِيطٍ ‏ ‏عَنْ ‏ ‏جَابَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏مَنَّانٌ ‏ ‏وَلَا ‏ ‏عَاقٌّ ‏ ‏وَالِدَيْهِ وَلَا مُدْمِنُ خَمْرٍ ‏","","",""],[6588,6588,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ الرَّجُلِ قَاعِدًا فَقَالَ ‏ ‏عَلَى النِّصْفِ مِنْ صَلَاتِهِ قَائِمًا ‏","","",""],[6589,6589,"","","‏ ‏قَالَ وَأَبْصَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمًا يَتَوَضَّئُونَ لَمْ يُتِمُّوا الْوُضُوءَ فَقَالَ ‏ ‏أَسْبِغُوا ‏ ‏يَعْنِي الْوُضُوءَ وَيْلٌ ‏ ‏لِلْعَرَاقِيبِ ‏ ‏مِنْ النَّارِ ‏ ‏أَوْ الْأَعْقَابِ ‏","","",""],[6590,6590,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْكَبَائِرُ الْإِشْرَاكُ بِاللَّهِ عَزَّ وَجَلَّ وَعُقُوقُ الْوَالِدَيْنِ ‏ ‏أَوْ قَتْلُ النَّفْسِ ‏ ‏شُعْبَةُ ‏ ‏الشَّاكُّ ‏ ‏وَالْيَمِينُ الْغَمُوسُ ‏","","",""],[6591,6591,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ الْبَرَّاءُ ‏ ‏حَدَّثَنِي ‏ ‏صَدَقَةُ بْنُ طَيْسَلَةَ ‏ ‏حَدَّثَنِي ‏ ‏مَعْنُ بْنُ ثَعْلَبَةَ الْمَازِنِيُّ ‏ ‏وَالْحَيُّ بَعْدُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْأَعْشَى الْمَازِنِيُّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْشَدْتُهُ ‏ ‏يَا مَالِكَ النَّاسِ وَدَيَّانَ ‏ ‏الْعَرَبْ ‏ ‏إِنِّي لَقِيتُ ذِرْبَةً مِنْ ‏ ‏الذِّرَبْ ‏ ‏غَدَوْتُ ‏ ‏أَبْغِيهَا الطَّعَامَ فِي ‏ ‏رَجَبْ ‏ ‏فَخَلَّفَتْنِي بِنِزَاعٍ ‏ ‏وَهَرَبْ ‏ ‏أَخْلَفَتْ الْعَهْدَ وَلَطَّتْ ‏ ‏بِالذَّنَبْ ‏ ‏وَهُنَّ شَرُّ غَالِبٍ لِمَنْ ‏ ‏غَلَبْ ‏ ‏قَالَ فَجَعَلَ يَقُولُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ ‏ ‏وَهُنَّ شَرُّ غَالِبٍ لِمَنْ ‏ ‏غَلَبْ ‏","","",""],[6592,6592,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ عُبَيْدُ بْنُ عَبْدِ الرَّحْمَنِ الْحَنَفِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْجُنَيْدُ بْنُ أَمِينِ بْنِ ذِرْوَةَ بْنِ نَضْلَةَ بْنِ طَرِيفِ بْنِ بُهْصُلٍ الْحِرْمَازِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَمِيْنُ بْنُ ذِرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏ذِرْوَةَ بْنِ نَضْلَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏نَضْلَةَ بْنِ طَرِيفٍ ‏ ‏أَنَّ رَجُلًا مِنْهُمْ يُقَالُ لَهُ ‏ ‏الْأَعْشَى ‏ ‏وَاسْمُهُ ‏ ‏عَبْدُ اللَّهِ بْنُ الْأَعْوَرِ ‏ ‏كَانَتْ عِنْدَهُ امْرَأَةٌ يُقَالُ لَهَا ‏ ‏مُعَاذَةُ ‏ ‏خَرَجَ فِي رَجَبٍ ‏ ‏يَمِيرُ ‏ ‏أَهْلَهُ مِنْ ‏ ‏هَجَرَ ‏ ‏فَهَرَبَتْ امْرَأَتُهُ بَعْدَهُ ‏ ‏نَاشِزًا ‏ ‏عَلَيْهِ فَعَاذَتْ بِرَجُلٍ مِنْهُمْ يُقَالُ لَهُ ‏ ‏مُطَرِّفُ بْنُ بُهْصُلِ بْنِ كَعْبِ بْنِ قَمَيْشَعِ بْنِ دُلَفَ بْنِ أَهْضَمَ بْنِ عَبْدِ اللَّهِ ‏ ‏فَجَعَلَهَا خَلْفَ ظَهْرِهِ فَلَمَّا قَدِمَ وَلَمْ يَجِدْهَا فِي بَيْتِهِ وَأُخْبِرَ أَنَّهَا ‏ ‏نَشَزَتْ ‏ ‏عَلَيْهِ وَأَنَّهَا عَاذَتْ ‏ ‏بِمُطَرِّفِ بْنِ بُهْصُلٍ ‏ ‏فَأَتَاهُ فَقَالَ يَا ابْنَ عَمِّ أَعِنْدَكَ امْرَأَتِي ‏ ‏مُعَاذَةُ ‏ ‏فَادْفَعْهَا إِلَيَّ قَالَ لَيْسَتْ عِنْدِي وَلَوْ كَانَتْ عِنْدِي لَمْ أَدْفَعْهَا إِلَيْكَ قَالَ وَكَانَ ‏ ‏مُطَرِّفٌ ‏ ‏أَعَزَّ مِنْهُ فَخَرَجَ حَتَّى أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَاذَ بِهِ وَأَنْشَأَ يَقُولُ ‏ ‏يَا سَيِّدَ النَّاسِ وَدَيَّانَ ‏ ‏الْعَرَبْ ‏ ‏إِلَيْكَ أَشْكُو ‏ ‏ذِرْبَةً ‏ ‏مِنْ ‏ ‏الذِّرَبْ ‏ ‏كَالذِّئْبَةِ ‏ ‏الْغَبْشَاءِ ‏ ‏فِي ظِلِّ ‏ ‏السَّرَبْ ‏ ‏خَرَجْتُ ‏ ‏أَبْغِيهَا الطَّعَامَ فِي ‏ ‏رَجَبْ ‏ ‏فَخَلَّفَتْنِي بِنِزَاعٍ ‏ ‏وَهَرَبْ ‏ ‏أَخْلَفَتْ الْعَهْدَ وَلَطَّتْ ‏ ‏بِالذَّنَبْ ‏ ‏وَقَذَفَتْنِي بَيْنَ ‏ ‏عِيصٍ ‏ ‏مُؤْتَشَبْ ‏ ‏وَهُنَّ شَرُّ غَالِبٍ لِمَنْ ‏ ‏غَلَبْ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ ‏ ‏وَهُنَّ شَرُّ غَالِبٍ لِمَنْ ‏ ‏غَلَبْ فَشَكَا إِلَيْهِ امْرَأَتَهُ وَمَا صَنَعَتْ بِهِ وَأَنَّهَا عِنْدَ رَجُلٍ مِنْهُمْ يُقَالُ لَهُ ‏ ‏مُطَرِّفُ بْنُ بُهْصُلٍ ‏ ‏فَكَتَبَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏مُطَرِّفٍ ‏ ‏انْظُرْ امْرَأَةَ هَذَا ‏ ‏مُعَاذَةَ ‏ ‏فَادْفَعْهَا إِلَيْهِ فَأَتَاهُ كِتَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُرِئَ عَلَيْهِ فَقَالَ لَهَا يَا ‏ ‏مُعَاذَةُ ‏ ‏هَذَا كِتَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيكِ فَأَنَا دَافِعُكِ إِلَيْهِ قَالَتْ خُذْ لِي عَلَيْهِ الْعَهْدَ وَالْمِيثَاقَ وَذِمَّةَ نَبِيِّهِ لَا يُعَاقِبُنِي فِيمَا صَنَعْتُ فَأَخَذَ لَهَا ذَاكَ عَلَيْهِ وَدَفَعَهَا ‏ ‏مُطَرِّفٌ ‏ ‏إِلَيْهِ فَأَنْشَأَ يَقُولُ ‏ ‏لَعَمْرُكَ مَا حُبِّي ‏ ‏مُعَاذَةَ ‏ ‏بِالَّذِي ‏ ‏يُغَيِّرُهُ الْوَاشِي وَلَا قِدَمُ الْعَهْدِ ‏ ‏وَلَا سُوءُ مَا جَاءَتْ بِهِ إِذْ أَزَالَهَا ‏ ‏غُوَاةُ الرِّجَالِ إِذْ يُنَاجُونَهَا بَعْدِي ‏","","",""],[6593,6593,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاقِفًا عَلَى رَاحِلَتِهِ ‏ ‏بِمِنًى ‏ ‏قَالَ فَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ أَرَى أَنَّ الْحَلْقَ قَبْلَ الذَّبْحِ فَحَلَقْتُ قَبْلَ أَنْ أَذْبَحَ فَقَالَ اذْبَحْ وَلَا حَرَجَ قَالَ ثُمَّ جَاءَهُ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ أَرَى أَنَّ الذَّبْحَ قَبْلَ الرَّمْيِ فَذَبَحْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ فَارْمِ وَلَا حَرَجَ قَالَ ‏ ‏فَمَا سُئِلَ عَنْ شَيْءٍ قَدَّمَهُ رَجُلٌ قَبْلَ شَيْءٍ إِلَّا قَالَ افْعَلْ وَلَا حَرَجَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَجَاءَهُ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ أَظُنُّ أَنَّ الْحَلْقَ قَبْلَ الرَّمْيِ فَحَلَقْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ارْمِ وَلَا حَرَجَ ‏","","",""],[6594,6594,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏سَمِعْتُ ‏ ‏الْأَوْزَاعِيَّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي كَبْشَةَ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلِّغُوا عَنِّي وَلَوْ آيَةً وَحَدِّثُوا عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَلَا حَرَجَ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[6595,6595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سَعْدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَقَالَ إِنَّمَا أَسْأَلُكَ عَمَّا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا أَسْأَلُكَ عَنْ التَّوْرَاةِ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ ‏","","",""],[6596,6596,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عَبْدِ اللَّهِ بْنِ عُلَاثَةَ الْقَاضِي أَبُو سَهْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ رَافِعٍ ‏ ‏عَنِ ‏ ‏الْفَرَزْدَقِ بْنِ حَنَانٍ الْقَاصِّ ‏ ‏قَالَ ‏ ‏أَلَا أُحَدِّثُكُمْ حَدِيثًا سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي لَمْ أَنْسَهُ بَعْدُ ‏ ‏خَرَجْتُ أَنَا ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ حَيْدَةَ ‏ ‏فِي طَرِيقِ ‏ ‏الشَّامِ ‏ ‏فَمَرَرْنَا ‏ ‏بِعَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ جَاءَ رَجُلٌ مِنْ قَوْمِكُمَا أَعْرَابِيٌّ جَافٍ جَرِيءٌ فَقَالَ يَا رَسُولَ اللَّهِ أَيْنَ الْهِجْرَةُ إِلَيْكَ حَيْثُمَا كُنْتَ أَمْ إِلَى أَرْضٍ مَعْلُومَةٍ أَوْ لِقَوْمٍ خَاصَّةً أَمْ إِذَا مُتَّ انْقَطَعَتْ قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاعَةً ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ الْهِجْرَةِ قَالَ هَا أَنَا ذَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِذَا أَقَمْتَ الصَّلَاةَ وَآتَيْتَ الزَّكَاةَ فَأَنْتَ مُهَاجِرٌ وَإِنْ مُتَّ ‏ ‏بِالْحَضْرَمَةِ ‏ ‏قَالَ ‏ ‏يَعْنِي أَرْضًا ‏ ‏بِالْيَمَامَةِ ‏ ‏قَالَ ثُمَّ قَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ ثِيَابَ أَهْلِ الْجَنَّةِ أَتُنْسَجُ نَسْجًا أَمْ تُشَقَّقُ مِنْ ثَمَرِ الْجَنَّةِ قَالَ فَكَأَنَّ الْقَوْمَ تَعَجَّبُوا مِنْ مَسْأَلَةِ الْأَعْرَابِيِّ فَقَالَ مَا تَعْجَبُونَ مِنْ جَاهِلٍ يَسْأَلُ عَالِمًا قَالَ فَسَكَتَ هُنَيَّةً ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ ثِيَابِ الْجَنَّةِ قَالَ أَنَا قَالَ لَا بَلْ تُشَقَّقُ مِنْ ثَمَرِ الْجَنَّةِ ‏","","",""],[6597,6597,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجُلًا مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏يَسْأَلُهُ عَنْ ضَالَّةِ الْإِبِلِ فَقَالَ ‏ ‏مَعَهَا حِذَاؤُهَا وَسِقَاؤُهَا تَأْكُلُ الشَّجَرَ وَتَرِدُ الْمَاءَ فَذَرْهَا حَتَّى يَأْتِيَ بَاغِيهَا قَالَ وَسَأَلَهُ عَنْ ضَالَّةِ الْغَنَمِ فَقَالَ لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ اجْمَعْهَا إِلَيْكَ حَتَّى يَأْتِيَ بَاغِيهَا وَسَأَلَهُ عَنْ ‏ ‏الْحَرِيسَةِ ‏ ‏الَّتِي تُوجَدُ فِي ‏ ‏مَرَاتِعِهَا ‏ ‏قَالَ فَقَالَ فِيهَا ثَمَنُهَا مَرَّتَيْنِ وَضَرْبُ ‏ ‏نَكَالٍ ‏ ‏قَالَ فَمَا أُخِذَ مِنْ ‏ ‏أَعْطَانِهِ ‏ ‏فَفِيهِ الْقَطْعُ إِذَا بَلَغَ مَا يُؤْخَذُ مِنْ ذَلِكَ ثَمَنَ ‏ ‏الْمِجَنِّ ‏ ‏فَسَأَلَهُ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏اللُّقَطَةُ ‏ ‏نَجِدُهَا فِي السَّبِيلِ ‏ ‏الْعَامِرِ ‏ ‏قَالَ عَرِّفْهَا سَنَةً فَإِنْ جَاءَ صَاحِبُهَا وَإِلَّا فَهِيَ لَكَ قَالَ يَا رَسُولَ اللَّهِ مَا يُوجَدُ فِي الْخَرَابِ ‏ ‏الْعَادِيِّ قَالَ فِيهِ وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[6598,6598,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏عَاقٌّ ‏ ‏وَلَا مُدْمِنُ خَمْرٍ وَلَا ‏ ‏مَنَّانٌ ‏ ‏وَلَا وَلَدُ زِنْيَةٍ ‏","","",""],[6599,6599,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏سَمِعْتُ ‏ ‏الْمُثَنَّى بْنُ الصَّبَّاحِ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّ ‏ ‏الْمَرْأَةَ أَحَقُّ بِوَلَدِهَا مَا لَمْ تَزَوَّجْ ‏","","",""],[6600,6600,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي قَاعِدًا فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي حُدِّثْتُ أَنَّكَ قُلْتَ أَنَّ صَلَاةَ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ وَأَنْتَ تُصَلِّي جَالِسًا قَالَ أَجَلْ وَلَكِنِّي لَسْتُ كَأَحَدٍ مِنْكُمْ ‏","","",""]];
